local config = {
  ui_story_5009_50090101_1_dialog_content = "Ini surat pertama yang kukirimkan dari Eraveil.",
  ui_story_5009_50090101_2_dialog_content = "Saya ingin berterima kasih kepada Lins ... ya, Lin Guild, karena telah memberikan pemakaman yang layak kepada kerabat saya yang telah meninggal.",
  ui_story_5009_50090101_3_dialog_content = "Oh, ini juga surat pertama yang kudapatkan di Eraveil.",
  ui_story_5009_50090101_4_dialog_content = "Sudah berapa lama surat ini terkucil dari dunia? 17 tahun, ya?",
  ui_story_5009_50090101_5_dialog_content = "Lihat, ini Eraveil Post. Tempat ini sudah berdiri sejak seratus tahun lalu.",
  ui_story_5009_50090101_6_dialog_content = "Saya tidak menyadari akan menjadi tugas yang berbahaya untuk merenovasinya saat itu.",
  ui_story_5009_50090101_7_dialog_content = "<color=#e8d9bb>Kilas balik ke kisah awalnya...</color>",
  ui_story_5009_50090101_8_dialog_content = "Sangat menyenangkan bisa tidur nyenyak.",
  ui_story_5009_50090101_9_dialog_content = "\"(Bip) 2 hari lagi menuju Windelion.\"",
  ui_story_5009_50090101_10_dialog_content = "Jangan ingatkan aku lagi. Aku tahu, kok. Aku tahu.",
  ui_story_5009_50090101_11_dialog_content = "Sudahlah, aku mau tidur lagi saja.",
  ui_story_5009_50090101_12_dialog_content = "\"(Bip) Wakil ada di telepon.\"",
  ui_story_5009_50090101_13_dialog_content = "Bagaimana kabarmu akhir-akhir ini, PlayerName?",
  ui_story_5009_50090101_14_dialog_content = "Kali ini kau punya waktu lebih dari 30 detik untukku?",
  ui_story_5009_50090101_15_dialog_content = "Saya minta maaf. Saya dibanjiri beberapa hari yang lalu dan tidak punya pilihan selain menutup telepon Anda ...",
  ui_story_5009_50090101_16_dialog_content = "Aku baik-baik saja dengan itu, hanya sedikit khawatir.",
  ui_story_5009_50090101_17_dialog_content = "Maaf, saya sedang sibuk menyelesaikan laporan Dunefire Strike.",
  ui_story_5009_50090101_18_dialog_content = "Bagaimana kabarmu di Eraveil?",
  ui_story_5009_50090101_19_dialog_content = "Aku baik-baik saja. Lagipula, tidak banyak yang bisa dilakukan,",
  ui_story_5009_50090101_20_dialog_content = "selain membaca dan mempelajari berbagai keterampilan sehari-hari.",
  ui_story_5009_50090101_21_dialog_content = "Oh? Keterampilan apa?",
  ui_story_5009_50090101_22_dialog_content = "Menjahit, kerajinan tangan, menggambar, hal-hal seperti itu.",
  ui_story_5009_50090101_23_dialog_content = "Aku akan berakhir menjadi juru masak yang lebih baik daripada kamu jika kamu tidak segera kembali.",
  ui_story_5009_50090101_24_dialog_content = "Dalam mimpimu! Saya telah mempelajari seni kuliner lebih lama dari Anda.",
  ui_story_5009_50090101_25_dialog_content = "Mempelajari? Seperti dalam...",
  ui_story_5009_50090101_26_dialog_content = "Tentu saja, bereksperimen membuat berbagai hidangan baru! Kau harus mencicipi hidangan...",
  ui_story_5009_50090101_27_dialog_content = "Ahem! Tidak apa-apa. Mari kita bicara tentang hal lain.",
  ui_story_5009_50090101_28_dialog_content = "Oh, akhir-akhir ini aku merasakan lebih banyak Eclipsites di Eraveil.",
  ui_story_5009_50090101_29_dialog_content = "Yah. Menurut laporan terbaru, sebagian Eclipsite yang lolos dari Dunefire memang kabur menuju Eraveil.",
  ui_story_5009_50090101_30_dialog_content = "Hati-hati, ya, dan jangan berkeliaran sendirian!",
  ui_story_5009_50090101_31_dialog_content = "Santai! Aku akan tetap diam. Saya tidak akan mengisi daya ke Eraveil tanpa alasan, jangan khawatir.",
  ui_story_5009_50090101_32_dialog_content = "Itu membuat saya merasa jauh lebih baik.",
  ui_story_5009_50090101_33_dialog_content = "Baiklah, sana, uruslah kesibukanmu lagi.",
  ui_story_5009_50090101_34_dialog_content = "\"(Bip) 2 hari lagi menuju Windelion.\"",
  ui_story_5009_50090101_35_dialog_content = "Ya ampun, pengingat ini lama-lama jadi menjengkelkan!",
  ui_story_5009_50090101_36_dialog_content = "Tunggu, apakah itu hanya mengatakan Windelion?",
  ui_story_5009_50090101_37_dialog_content = "Ya, Festival Windelion. Anda tahu tentang itu?",
  ui_story_5009_50090101_38_dialog_content = "Tentu saja, itu kan festival Aurorian!",
  ui_story_5009_50090101_39_dialog_content = "Biarkan saya mengingat apa yang dikatakan buku-buku itu ... Oh ya!",
  ui_story_5009_50090101_A1_dialog_content = "Windelion adalah tradisi dari kaum Caelestite. Itu adalah hari perayaan untuk mengenang para orang suci dan memuja Cahaya...",
  ui_story_5009_50090101_40_dialog_content = "Tunggu. Bagaimana Caelestites merayakan Windelion, PlayerName?",
  ui_story_5009_50090101_41_dialog_content = "Kami berkumpul bersama untuk memperingati almarhum orang-orang terkasih dan memuji Ibu Pertiwi.",
  ui_story_5009_50090101_42_dialog_content = "Nah, itulah yang dikatakan Soroz kepada saya. Soroz biasa membacakan tradisi ini kepada saya setiap tahun.",
  ui_story_5009_50090101_43_dialog_content = "Kemudian saya akan membayangkan seperti apa pertemuan itu, seperti apa rupa orang-orang yang saya cintai, seperti apa...",
  ui_story_5009_50090101_44_dialog_content = "Sudahlah, mari kita lanjutkan.",
  ui_story_5009_50090101_45_dialog_content = "Omong-omong, ini akan jadi Windelion pertama yang kaurayakan di permukaan tanah.",
  ui_story_5009_50090101_46_dialog_content = "Hmm, ya. Yah, aku harus pergi sekarang. Sampai jumpa untuk saat ini, Vice.",
  ui_story_5009_50090101_47_dialog_content = "Oke. Sampai jumpa lagi, PlayerName.",
  ui_story_5009_50090101_48_dialog_content = "\"(Bip) 2 hari lagi menuju...\"",
  ui_story_5009_50090101_49_dialog_content = "Baiklah, baiklah!",
  ui_story_5009_50090101_50_dialog_content = "\"Windelion pertama di permukaan tanah\"... Kedengarannya memang istimewa.",
  ui_story_5009_50090101_51_dialog_content = "Firefly! Firefly!",
  ui_story_5009_50090101_52_dialog_content = "\"Siap melayani.\"",
  ui_story_5009_50090101_53_dialog_content = "Ayo kita hadirkan suasana Windelion di tempat ini!",
  ui_story_5009_50090101_54_dialog_content = "\"Perintah dikonfirmasi. Mode bantuan diaktifkan.\"",
  ui_story_5009_50090101_55_dialog_content = "(Bip) 2 hari lagi menuju perayaan Windelion. Mari kita hias ruang-ruang di sini.\"",
  ui_story_5009_50090101_56_dialog_content = "\"Menghias ruang untuk menyambut festival. Menghias ruang untuk menyambut festival.\"",
  ui_story_5009_50090101_57_dialog_content = "\"Harap masukkan jenis dekorasi yang diinginkan.\"",
  ui_story_5009_50090101_58_dialog_content = "Hmm, aku perlu memikirkan ini... Seperti apa sebenarnya Windelion?",
  ui_story_5009_50090101_59_dialog_content = "Aduh, memikirkannya saja membuatku pusing.",
  ui_story_5009_50090101_60_dialog_content = "Ayolah, Soroz!",
  ui_story_5009_50090101_61_dialog_content = "Beri tahu aku, apa yang harus kusiapkan untuk Windelion!",
  ui_story_5009_50090201_1_dialog_content = "Bolehkah aku bicara denganmu, Yang Mulia?",
  ui_story_5009_50090201_2_dialog_content = "Aku mengenalmu. Kau dari gereja, 'kan?",
  ui_story_5009_50090201_3_dialog_content = "Sebenarnya, aku hakim dari Lumopolis, Yang Mulia. Namaku Wayne Pittman.",
  ui_story_5009_50090201_4_dialog_content = "Oh, pantas saja wajahmu tampak familier.",
  ui_story_5009_50090201_5_dialog_content = "Aku sedang mempelajari peningkatan yang dialami para Eclipsite, jadi aku ingin bertanya kepadamu...",
  ui_story_5009_50090201_6_dialog_content = "Jangan sungkan-sungkan, tanyakan saja segala yang ingin kauketahui.",
  ui_story_5009_50090201_7_dialog_content = "Terima kasih. Kudengar belum lama ini kau bertemu dengan Beryl Gautier, bukan?",
  ui_story_5009_50090201_8_dialog_content = "Iya.",
  ui_story_5009_50090201_9_dialog_content = "Aku sudah membaca laporanmu tentang insiden pertemuan dengan Beryl dan Caroline, dan aku ingin tahu tentang keberadaan mereka.",
  ui_story_5009_50090201_10_dialog_content = "Caroline Pyrrhus? Kami sudah mengatasinya.",
  ui_story_5009_50090201_11_dialog_content = "Ini rumit. Saya akan melanjutkan penyelidikan saya. Tolong beri tahu saya jika Anda menerima lebih banyak berita.",
  ui_story_5009_50090201_12_dialog_content = "Rumit? Caroline kalah, bukankah itu cukup?",
  ui_story_5009_50090201_13_dialog_content = "Yah, sebenarnya yang kumaksud adalah kemunculan kembali House Pyrrhus dan Gautier.",
  ui_story_5009_50090201_14_dialog_content = "Bukannya itu sudah teratasi bertahun-tahun lalu?",
  ui_story_5009_50090201_15_dialog_content = "Ini rumit. Aku butuh banyak bukti agar bisa menarik kesimpulan yang pasti.",
  ui_story_5009_50090201_16_dialog_content = "Saya mengerti. Aku akan meninggalkan Anda untuk itu kemudian.",
  ui_story_5009_50090201_17_dialog_content = "Kalau kau mau ke Eraveil, tolong izinkan aku ikut denganmu.",
  ui_story_5009_50090201_18_dialog_content = "Maksudmu?",
  ui_story_5009_50090201_19_dialog_content = "Dalam laporan tentang Dunefire Strike, aku menemukan sejumlah petunjuk samar.",
  ui_story_5009_50090201_A1_dialog_content = "Aku punya alasan yang membuatku yakin bahwa kali ini para Eclipsite itu merencanakan sesuatu yang lebih besar.",
  ui_story_5009_50090201_20_dialog_content = "Menurut laporan tersebut, sebagian Eclipsite yang kalah itu berkumpul menuju Eraveil. Aku curiga...",
  ui_story_5009_50090201_21_dialog_content = "Baiklah. Kamu boleh ikut. Kita bahas soal itu sambil jalan.",
  ui_story_5009_50090201_22_dialog_content = "Boneka... Windelion.",
  ui_story_5009_50090201_23_dialog_content = "\"Boneka Windelion, hiasan khusus untuk perayaan Windelion. Tampak menenangkan dan menggemaskan.\"",
  ui_story_5009_50090201_24_dialog_content = "\"Caelestites akan mengisi boneka dengan permen atau biji-bijian dan membukanya selama festival.\"",
  ui_story_5009_50090201_25_dialog_content = "\"Ini adalah bentuk permainan untuk mengucap syukur dan memohon berkat, dan semua anak menyukainya.\"",
  ui_story_5009_50090201_26_dialog_content = "Tapi, boneka ini tampak seperti...",
  ui_story_5009_50090201_27_dialog_content = "\"Teridentifikasi, seperti kodok.\"",
  ui_story_5009_50090201_28_dialog_content = "\"Teridentifikasi, seperti laba-laba.\"",
  ui_story_5009_50090201_29_dialog_content = "\"Teridentifikasi, seperti kelelawar.\"",
  ui_story_5009_50090201_30_dialog_content = "Firefly bahkan tidak bisa mengatakan bahwa ini seharusnya Soroz... Mungkin saya baru saja melakukan pekerjaan yang sangat buruk untuk membuatnya?",
  ui_story_5009_50090201_31_dialog_content = "PlayerName!",
  ui_story_5009_50090201_32_dialog_content = "Saya tidak berharap untuk mendengar dari Anda! Saya pikir Anda akan sibuk hari ini juga.",
  ui_story_5009_50090201_33_dialog_content = "Kita hampir sampai di Eraveil!",
  ui_story_5009_50090201_34_dialog_content = "Apa? Anda sedang dalam perjalanan ke sini ?!",
  ui_story_5009_50090201_35_dialog_content = "Tapi bukankah Anda dibanjiri pekerjaan?",
  ui_story_5009_50090201_36_dialog_content = "Aku punya kejutan untukmu. Sampai jumpa.",
  ui_story_5009_50090201_37_dialog_content = "Asyik, Vice mau berkunjung kemari!",
  ui_story_5009_50090201_38_dialog_content = "\"Kamu wajib menjamu para tamu selama festival.\"",
  ui_story_5009_50090201_39_dialog_content = "Ya, aku harus mengatur segalanya sebelum dia tiba di sini.",
  ui_story_5009_50090201_40_dialog_content = "Kami sudah sampai, PlayerName!",
  ui_story_5009_50090201_41_dialog_content = "Selamat datang kembali, Vice.",
  ui_story_5009_50090201_42_dialog_content = "Kenapa kamu berpakaian seperti ayam jago ?!",
  ui_story_5009_50090201_43_dialog_content = "Jadi ini adalah gaya busana pilihan Anda...",
  ui_story_5009_50090201_44_dialog_content = "Tidak, biar kujelaskan, Carleen!",
  ui_story_5009_50090201_45_dialog_content = "Kuwasa PlayerName suka pakaian mewrah!",
  ui_story_5009_50090201_46_dialog_content = "Tweety juga di sini? Hei, siapa orang-orang ini?",
  ui_story_5009_50090201_47_dialog_content = "Mereka di sini untuk membantu membersihkan Eraveil.",
  ui_story_5009_50090201_48_dialog_content = "Membersihkan?",
  ui_story_5009_50090201_49_dialog_content = "Bukankah Anda mengatakan lebih banyak Eclipsites masuk ke Eraveil?",
  ui_story_5009_50090201_50_dialog_content = "Jadi kita harus bersih-bersih dulu, baru boleh pulang.",
  ui_story_5009_50090201_51_dialog_content = "Omong-omong, kita kedatangan tamu penting di sini. Dia...",
  ui_story_5009_50090201_52_dialog_content = "Senang bertemu denganmu, aku Naroxel, wakil dari Courier Union.",
  ui_story_5009_50090201_53_dialog_content = "Terima kasih Ibu Pertiwi karena akhirnya membimbing saya kepada Anda, perwakilan dari Caelestites.",
  ui_story_5009_50090201_54_dialog_content = "Uh, perwakilan dari Caelestites? Saya kira bisa hidup dengan itu. Bagaimana kabarmu, aku PlayerName.",
  ui_story_5009_50090201_55_dialog_content = "Hiasan kepalamu... bagus sekali.",
  ui_story_5009_50090201_56_dialog_content = "Seperti nyala api dan dedaunan merah yang berjatuhan saat musim gugur.",
  ui_story_5009_50090201_57_dialog_content = "Terima kasih! Senang bertemu denganmu!",
  ui_story_5009_50090201_58_dialog_content = "Jangan terlalu menyanjungnya, Naroxel. Saya tidak ingin dia mendapatkan ide yang salah tentang dirinya sendiri.",
  ui_story_5009_50090201_59_dialog_content = "Aku akan menurunkannya. Itu hanya dekorasi untuk festival.",
  ui_story_5009_50090201_60_dialog_content = "Windelion.",
  ui_story_5009_50090201_61_dialog_content = "Ya, ya, besok perayaan Windelion!",
  ui_story_5009_50090201_62_dialog_content = "Ini adalah festival Caelestite bagi kita untuk memperingati leluhur dan alam kita.",
  ui_story_5009_50090201_63_dialog_content = "Orang Caelest akan merapikan rumah mereka, berdandan, dan...",
  ui_story_5009_50090201_64_dialog_content = "Wow. Apakah ruangan yang berantakan dan penutup kepala yang aneh ini merupakan bagian dari tradisi festival?",
  ui_story_5009_50090201_65_dialog_content = "Tidak! Saya hanya mengikuti arahan Soroz dan... bereksperimen sedikit. Meskipun saya mungkin mengacau di suatu tempat.",
  ui_story_5009_50090201_66_dialog_content = "Bagaimana dengan tumpukan kotoran ini?",
  ui_story_5009_50090201_67_dialog_content = "Saya ingin mendapatkan beberapa dandelion dari Eraveil untuk ditanam dalam pot.",
  ui_story_5009_50090201_68_dialog_content = "Tapi tidak ada dandelion, jadi saya hanya berakhir dengan kotoran... Saya akan mencoba membuatnya terlihat lebih baik.",
  ui_story_5009_50090201_69_dialog_content = "Dan apa laba-laba dengan mata katak dan sayap kelelawar di sudut?",
  ui_story_5009_50090201_70_dialog_content = "Bukan apa-apa, tak usah dipikirkan!",
  ui_story_5009_50090201_71_dialog_content = "*Ahem* Saya datang ke sini atas nama Serikat Kurir untuk...",
  ui_story_5009_50090201_72_dialog_content = "Untuk mengantarkan hadiah khusus untukku?",
  ui_story_5009_50090201_73_dialog_content = "Apakah itu karena penghargaan atas keberanian saya melawan Eclipsites di seluruh negeri?",
  ui_story_5009_50090201_74_dialog_content = "Simpan saja fantasimu itu, PlayerName.",
  ui_story_5009_50090201_75_dialog_content = "Bisa dibilang ini memang hadiah, tapi kami lebih suka menyebutnya misi.",
  ui_story_5009_50090201_76_dialog_content = "Sebuah misi? Hadiah macam apa ini?",
  ui_story_5009_50090201_77_dialog_content = "Selama seratus tahun, Union telah menyediakan layanan untuk Eraveil dan Caelestites.",
  ui_story_5009_50090201_78_dialog_content = "Tapi surat ke dan dari Eraveil berhenti sama sekali sejak kejadian 17 tahun lalu.",
  ui_story_5009_50090201_79_dialog_content = "Karena kami tak bisa masuk ke Eraveil atau mencari keberadaan para penerima surat, sebagian besar surat yang dialamatkan ke sini terpaksa hanya bisa disimpan di gudang kami.",
  ui_story_5009_50090201_80_dialog_content = "Aku sedih sekawi mewihat suwat-suwat itu tewtutup debu.",
  ui_story_5009_50090201_81_dialog_content = "Kami selalu berharap dapat mengirimkannya ke Caelestites suatu hari nanti.",
  ui_story_5009_50090201_82_dialog_content = "Karena Anda sekarang satu-satunya perwakilan mereka ...",
  ui_story_5009_50090201_83_dialog_content = "Oh, begitu. Apa kau membawa suratnya?",
  ui_story_5009_50090201_84_dialog_content = "Mereka harus dikirim ke pos atau kembali ke penyimpanan, aturan serikat pekerja.",
  ui_story_5009_50090201_85_dialog_content = "Pos? Apa itu?",
  ui_story_5009_50090201_86_dialog_content = "Posting adalah apa yang kami atur untuk memproses email. Itu didirikan setelah penduduk setempat dan cabang mencapai kesepakatan.",
  ui_story_5009_50090201_87_dialog_content = "Sudah bertahun-tahun kantor pos di Eraveil tidak beroperasi.",
  ui_story_5009_50090201_88_dialog_content = "Oh? Apa kita bisa memperbaikinya?",
  ui_story_5009_50090201_89_dialog_content = "Kita butuh pewbaikan dan izin pengaktifan dawi Caewestite. Kawau tidak, kita tak bisa mewakukannya.",
  ui_story_5009_50090201_90_dialog_content = "Baik. Sebenarnya, itu bahkan bukan hanya memperbaiki pos.",
  ui_story_5009_50090201_91_dialog_content = "Setiap kali saya berpikir tentang membangun kembali Eraveil, saya bertanya pada diri sendiri...",
  ui_story_5009_50090201_A2_dialog_content = "\"Apakah kaum Eclipsite akan membiarkanku melakukannya? Toh, nantinya paling-paling mereka akan menghancurkannya lagi...\"",
  ui_story_5009_50090201_92_dialog_content = "Mungkin sulit, tetapi kami akan melakukan yang terbaik untuk membantu.",
  ui_story_5009_50090201_93_dialog_content = "Kami membawa banyak orang kali ini karena kami ingin membersihkan Eclipsites dari sini. Kemudian Anda dapat mulai membangun kembali.",
  ui_story_5009_50090201_94_dialog_content = "Terima kasih, teman-teman.",
  ui_story_5009_50090201_95_dialog_content = "Sebelum kita mulai, biar kujelaskan dulu rencananya. Saat ini, ada dua kelompok Eclipsite di Eraveil.",
  ui_story_5009_50090201_96_dialog_content = "Pertama adalah yang mundur dari Dunefire, lalu ada yang telah berada di sini selama bertahun-tahun...",
  ui_story_5009_50090201_97_dialog_content = "Izinkan saya untuk menyela. Situasi spesifik seharusnya—",
  ui_story_5009_50090201_98_dialog_content = "Anda telah keluar dari barisan, Pittman.",
  ui_story_5009_50090201_99_dialog_content = "Maafkan saya karena bersikap kasar, Yang Mulia.",
  ui_story_5009_50090201_100_dialog_content = "Aku hanya ingin menyampaikan informasi terbaru.",
  ui_story_5009_50090201_101_dialog_content = "Siapa itu, Carleen?",
  ui_story_5009_50090201_102_dialog_content = "Ini hakim dari Lumopolis yang ingin mencari kebenaran di balik Dunefire Strike.",
  ui_story_5009_50090201_103_dialog_content = "Kebenaran?",
  ui_story_5009_50090201_104_dialog_content = "Apa kabarmu, PlayerName. Reputasi Anda mendahului Anda. Saya Penyelidik Wayne Pittman, dari Lumopolis.",
  ui_story_5009_50090201_105_dialog_content = "Mari kembali ke topik kita.",
  ui_story_5009_50090201_106_dialog_content = "Saya akan langsung ke intinya kalau begitu. Selain yang melarikan diri dari Garis Dunefire, Eclipsites dari area lain juga berkumpul di Eraveil.",
  ui_story_5009_50090201_107_dialog_content = "Kabarnya, Eclipsites dari Dunefire diadaptasi dalam hal kemampuan dan taktik.",
  ui_story_5009_50090201_108_dialog_content = "Aku khawatir mereka berniat melancarkan serangan besar ke Eraveil. Karena itulah aku kemari.",
  ui_story_5009_50090201_109_dialog_content = "Saya mengerti. Tapi terlepas dari apa yang mereka rencanakan, kemenangan akan menjadi milik Illumina.",
  ui_story_5009_50090201_110_dialog_content = "Kenapa harus Illumina?",
  ui_story_5009_50090201_111_dialog_content = "Kenapa harus Illumina?",
  ui_story_5009_50090201_112_dialog_content = "Ayo, kita harus pergi sekarang.",
  ui_story_5009_50090201_113_dialog_content = "Ayo kita basmi semua Eclipsite sebelum Windelion tiba!",
  ui_story_5009_50090301_1_dialog_content = "Gah!",
  ui_story_5009_50090301_2_dialog_content = "Aku tak menyangka kita akan menghadapi sekian banyak Eclipsite, padahal kita belum masuk.",
  ui_story_5009_50090301_3_dialog_content = "Ya, tapi jangan khawatir, tidak ada Eclipsites yang sangat kuat di antara mereka saat ini.",
  ui_story_5009_50090301_4_dialog_content = "Kalian semua sudah siap?",
  ui_story_5009_50090301_5_dialog_content = "Ya!",
  ui_story_5009_50090301_6_dialog_content = "Kalau begitu, ayo bergerak sesuai rencana dan mulai memberantas para Eclipsite itu!",
  ui_story_5009_50090301_7_dialog_content = "Serang!",
  ui_story_5009_50090301_8_dialog_content = "Itu mereka... Sepertinya mereka lebih antusias daripada aku!",
  ui_story_5009_50090301_9_dialog_content = "Antusiasmelah yang menjadi keuntungan bagi kami para prajurit Illumina Soldier. Tenanglah, mereka akan berhasil menjalankan operasinya.",
  ui_story_5009_50090301_10_dialog_content = "Kita bisa pergi ke kantor pos sekarang.",
  ui_story_5009_50090301_11_dialog_content = "Omong-omong soal itu, kita harus pergi ke arah mana, PlayerName?",
  ui_story_5009_50090301_12_dialog_content = "Uh... aku juga tidak yakin.",
  ui_story_5009_50090301_13_dialog_content = "Biar kuperiksa dulu panduan misiku. Ah, di sini tertulis...",
  ui_story_5009_50090301_14_dialog_content = "Kantor pos Courier Union berada di menara putih raksasa di timur laut Eraveil.",
  ui_story_5009_50090301_15_dialog_content = "Kok kamu bisa tahu, Pittman?",
  ui_story_5009_50090301_16_dialog_content = "Aku sudah pernah melakukan penyelidikan di tempat ini dan membaca banyak catatan tentang Eraveil.",
  ui_story_5009_50090301_17_dialog_content = "Timur laut seharusnya seperti ini...",
  ui_story_5009_50090301_18_dialog_content = "Apa ini...",
  ui_story_5009_50090301_19_dialog_content = "Ya, ini adalah tempat pemakaman Caelestite.",
  ui_story_5009_50090301_20_dialog_content = "Mereka yang meninggal 17 tahun lalu juga dimakamkan di sini.",
  ui_story_5009_50090301_21_dialog_content = "PlayerName...",
  ui_story_5009_50090301_22_dialog_content = "Aku tak apa-apa.",
  ui_story_5009_50090301_23_dialog_content = "Kuburan ini... mereka memiliki tanda Lins dari Umbraton.",
  ui_story_5009_50090301_24_dialog_content = "Tanda? Lin?",
  ui_story_5009_50090301_25_dialog_content = "Ya, penguburan duniawi dan batu nisan ini bergaya keluarga.",
  ui_story_5009_50090301_26_dialog_content = "Apa? Aku tak paham.",
  ui_story_5009_50090301_27_dialog_content = "Sederhananya, kelompok Lin-lah yang memakamkan kaummu dan meninggalkan pusara di makam ini.",
  ui_story_5009_50090301_28_dialog_content = "Mereka adalah salah satu guild paling terkenal di dunia. Vice dan Carleen, kalian berdua pasti mengenal mereka.",
  ui_story_5009_50090301_29_dialog_content = "Ya, aku juga tahu keluarga Lin berhubungan baik dengan Caelestites dan Northland.",
  ui_story_5009_50090301_30_dialog_content = "Tampaknya Naroxel benar bahwa keluarga Lin menguburkan Eraveil yang mati sesuai dengan kebiasaan mereka.",
  ui_story_5009_50090301_31_dialog_content = "Bagi kaum Caelestite, dimakamkan di dalam tanah berarti kembali ke alam, karena mereka akan menjadi bagian dari alam setelah mati.",
  ui_story_5009_50090301_32_dialog_content = "Lin Guild...",
  ui_story_5009_50090301_33_dialog_content = "Mari kita selesaikan dulu apa yang ingin kita lakukan di sini.",
  ui_story_5009_50090301_34_dialog_content = "Baiklah.",
  ui_story_5009_50090302_1_dialog_content = "Menara putih itu adalah tengara yang dikenal dengan nama Deepvalley Beacon...",
  ui_story_5009_50090302_2_dialog_content = "tidak boleh terlalu jauh ke depan.",
  ui_story_5009_50090302_3_dialog_content = "Kami akan berpisah menjadi dua kelompok. Aku akan menangani Eclipsites dengan Vice dan yang lainnya. Anda menuju pos.",
  ui_story_5009_50090302_4_dialog_content = "Oke! Lawiku cepat, aku akan memewiksanya!",
  ui_story_5009_50090302_5_dialog_content = "Dan kami akan mengurus perbaikan kantor posnya.",
  ui_story_5009_50090302_6_dialog_content = "Kami janji, saat kembali nanti, kau akan mendapati kantor posnya jadi seperti baru lagi.",
  ui_story_5009_50090302_7_dialog_content = "Aku yakin begitu. Terima kasih.",
  ui_story_5009_50090302_8_dialog_content = "Ayo terus menuju ke timur dan berantas para Eclipsite yang ada di sana.",
  ui_story_5009_50090302_9_dialog_content = "Oh, kehadiranmu juga diperlukan untuk sebuah upacara.",
  ui_story_5009_50090302_10_dialog_content = "Upacara apa?",
  ui_story_5009_50090302_11_dialog_content = "Tak usah khawatir, hanya butuh beberapa menit saja.",
  ui_story_5009_50090302_12_dialog_content = "Pertama, kami harus memverifikasi identitas Anda. Padahal tentu saja, itu sudah dilakukan.",
  ui_story_5009_50090302_13_dialog_content = "Lalu, ada dua dokumen yang harus kautandatangani.",
  ui_story_5009_50090302_14_dialog_content = "Pertama adalah Perjanjian Kantor Pos. Silakan tanda tangani. Lalu, tanda tangani dokumen Izin Kerja ini.",
  ui_story_5009_50090302_15_dialog_content = "Kedengarannya rumit... Coba saya lihat lebih dekat.",
  ui_story_5009_50090302_16_dialog_content = "Apakah ini benar-benar diperlukan sebelum pertempuran?",
  ui_story_5009_50090302_17_dialog_content = "<color=#e8d9bb>Beberapa menit kemudian…</color>",
  ui_story_5009_50090302_18_dialog_content = "Mataku agak kabur... Kutandatangani saja sekarang.",
  ui_story_5009_50090302_19_dialog_content = "Terakhir, ada Dokumen Verifikasi...",
  ui_story_5009_50090302_20_dialog_content = "Ini harus kutandatangani juga? Ya ampun, panjang sekali dokumennya!",
  ui_story_5009_50090302_21_dialog_content = "Tandatangani saja! Union dapat dipercaya, mereka tidak akan menipu Anda.",
  ui_story_5009_50090302_22_dialog_content = "Tapi, untuk dokumen dari pihak lain mana pun, kau harus membacanya dulu dengan cermat!",
  ui_story_5009_50090302_23_dialog_content = "Yang ini bisa ditandatangani nanti saja setelah kantor posnya selesai dibangun ulang.",
  ui_story_5009_50090302_24_dialog_content = "Selain itu, setelah kita sampai di kantor pos White Tower...",
  ui_story_5009_50090302_25_dialog_content = "Kami akan mengirimkan koordinatnya kepada pihak Union dan memberikan laporan kerusakan kepada mereka.",
  ui_story_5009_50090302_26_dialog_content = "Union akan mengirimkan bantuan sebagaimana mestinya agar kami bisa memastikan perbaikannya bisa selesai hari ini juga.",
  ui_story_5009_50090302_27_dialog_content = "Harap nantikan fasilitas baru.",
  ui_story_5009_50090302_28_dialog_content = "Nawoxel, aku wihat White Tower di sana!",
  ui_story_5009_50090302_29_dialog_content = "Kalau begitu, kita teruskan saja.",
  ui_story_5009_50090302_30_dialog_content = "Teruslah berusaha, PlayerName!",
  ui_story_5009_50090302_31_dialog_content = "Akan kucoba semampuku!",
  ui_story_5009_50090302_32_dialog_content = "Akan kami singkirkan semua Eclipsite di Eraveil!",
  ui_story_5009_50090401_1_dialog_content = "Target terlihat di arah timur laut!",
  ui_story_5009_50090401_2_dialog_content = "Saya saya. Putri cantik memasuki lembah untuk bertemu dengan kesatria menawannya...",
  ui_story_5009_50090401_3_dialog_content = "Dongeng cupu macam apa itu? Aku tak suka!",
  ui_story_5009_50090401_4_dialog_content = "Yah, kesempatan kita akhirnya tiba!",
  ui_story_5009_50090401_5_dialog_content = "Tapi ada banyak Aurorian di Eraveil sekarang...",
  ui_story_5009_50090401_6_dialog_content = "Bergerak... mungkin berisiko.",
  ui_story_5009_50090401_7_dialog_content = "Kaukira aku tak akan mampu mengalahkan mereka?",
  ui_story_5009_50090401_8_dialog_content = "Akan kuhabisi kau karena sudah merusak suasana hatiku!",
  ui_story_5009_50090401_9_dialog_content = "T-Tuanku...?",
  ui_story_5009_50090401_10_dialog_content = "Ha ha ha! Apakah kamu gemetar?",
  ui_story_5009_50090401_11_dialog_content = "Kali ini kuampuni kau, semata karena kau bisa bicara bahasa Universese.",
  ui_story_5009_50090401_12_dialog_content = "Tapi, tapi... si Caelestite itu juga ada.",
  ui_story_5009_50090401_13_dialog_content = "Kudengar dia bisa merasakan kita menggunakan kemampuan psikis.",
  ui_story_5009_50090401_14_dialog_content = "Memangnya kenapa?",
  ui_story_5009_50090401_15_dialog_content = "Tahu tidak, sebaiknya kutangkap saja Caelestite itu sekalian, untuk makan malamku.",
  ui_story_5009_50090401_16_dialog_content = "Aku memang genius!",
  ui_story_5009_50090401_17_dialog_content = "Sana, beri tahu yang lainnya dan suruh mereka bersiap!",
  ui_story_5009_50090401_18_dialog_content = "Bagaimana kemampuan psikismu, PlayerName?",
  ui_story_5009_50090401_19_dialog_content = "Saya tidak akan mengatakan itu sangat kuat, tetapi itu lebih dari cukup.",
  ui_story_5009_50090401_20_dialog_content = "Aku bisa merasakan lokasi para Eclipsite itu dari jauh dan membedakan mana yang punya kemampuan khusus.",
  ui_story_5009_50090401_21_dialog_content = "Apa kau tak keberatan menjelaskan perbedaan Eclipsite istimewa yang kautemui di Dunefire?",
  ui_story_5009_50090401_22_dialog_content = "Kebanyakan dari mereka adalah tipe rata-rata, hanya saja lebih ganas.",
  ui_story_5009_50090401_23_dialog_content = "Tapi elit yang kami temui di Undercity 13 sangat cerdas. Mereka adalah pejuang.",
  ui_story_5009_50090401_24_dialog_content = "Juga, mereka mampu mencari celah dan menggunakan badai pasir untuk berlindung.",
  ui_story_5009_50090401_25_dialog_content = "Ya, aku juga tahu tentang badai pasir itu.",
  ui_story_5009_50090401_26_dialog_content = "Menurut temuan saya, badai pasir dan fluks energi di Dunefire mungkin bukan fenomena alam.",
  ui_story_5009_50090401_27_dialog_content = "Setidaknya, tidak sepenuhnya alami.",
  ui_story_5009_50090401_28_dialog_content = "Maksudmu, para Eclipsite itu sekarang bisa mengendalikan cuaca?",
  ui_story_5009_50090401_29_dialog_content = "Itu baru dugaanku saja. Aku butuh bukti lebih banyak.",
  ui_story_5009_50090401_30_dialog_content = "Dan ada yang lebih rumit lagi.",
  ui_story_5009_50090401_31_dialog_content = "Ini bukan waktunya mengobrol. Aku merasakan kehadiran sekelompok besar Eclipsite di depan sana.",
  ui_story_5009_50090401_32_dialog_content = "Aku akan memimpin. Saya akan membagikan penilaian yang tepat ...",
  ui_story_5009_50090401_33_dialog_content = "Dan membasmi mereka semua!",
  ui_story_5009_50090502_1_dialog_content = "Semua sudah beres di sini! Ayo ke titik berikutnya.",
  ui_story_5009_50090502_2_dialog_content = "Tunggu, ada yang aneh!",
  ui_story_5009_50090502_3_dialog_content = "Siapa kau?",
  ui_story_5009_50090502_4_dialog_content = "Kau bisa bahasa Universese, Eclipsite?",
  ui_story_5009_50090502_5_dialog_content = "Kau pasti si musuh bebuyutan yang disebut-sebut Masterku...",
  ui_story_5009_50090502_6_dialog_content = "Wow, Eclipsites juga bisa mengoceh omong kosong?",
  ui_story_5009_50090502_7_dialog_content = "Ada banyak kaki tangannya kali ini... Sepertinya dia datang dengan penuh persiapan.",
  ui_story_5009_50090502_8_dialog_content = "Ini akan seru jadinya.",
  ui_story_5009_50090502_9_dialog_content = "Kenapa kau malah melamun, PlayerName?",
  ui_story_5009_50090502_10_dialog_content = "Saya baru saja merasakan gerombolan besar Eclipsites berkumpul di kuburan!",
  ui_story_5009_50090502_11_dialog_content = "Maka kita harus pergi ke sana sekarang!",
  ui_story_5009_50090502_12_dialog_content = "Tidak, mereka semua sudah binasa sekarang.",
  ui_story_5009_50090502_13_dialog_content = "Semuanya binasa?",
  ui_story_5009_50090502_14_dialog_content = "Baru saja...",
  ui_story_5009_50090502_15_dialog_content = "Ada energi kuat yang terlepas di pemakaman itu, dan para Eclipsite itu langsung binasa.",
  ui_story_5009_50090502_16_dialog_content = "Aku bisa merasakan, itu kekuatan Aurorian...",
  ui_story_5009_50090502_17_dialog_content = "Siapakah Aurorian itu? Kawan... atau lawan?",
  ui_story_5009_50090502_18_dialog_content = "Saya belum tahu, tapi Aurorian ini bisa menyembunyikan fluktuasi energinya!",
  ui_story_5009_50090502_19_dialog_content = "Untuk saat ini, aku tidak bisa merasakan keberadaan mereka.",
  ui_story_5009_50090502_20_dialog_content = "Kenapa mereka sembunyi...? Apa jangan-jangan mereka musuh tak dikenal?",
  ui_story_5009_50090502_21_dialog_content = "Kita harus hati-hati...",
  ui_story_5009_50090602_1_dialog_content = "Kau merasakan sesuatu, PlayerName?",
  ui_story_5009_50090602_2_dialog_content = "Aurorian yang sama seperti sebelumnya. Seseorang yang sangat kuat...",
  ui_story_5009_50090602_3_dialog_content = "Mungkinkah itu Naroxel? Dia kuat.",
  ui_story_5009_50090602_4_dialog_content = "Aku hanya mengajak Pittman.",
  ui_story_5009_50090602_5_dialog_content = "Tetapi Anda harus mengenal mereka.",
  ui_story_5009_50090602_6_dialog_content = "Seperti yang kuduga, Aurorian itu tidak ikut dengan kalian.",
  ui_story_5009_50090602_7_dialog_content = "Apa perlu kita kirimkan orang untuk memeriksanya?",
  ui_story_5009_50090602_8_dialog_content = "Tak usah. Aku ingat Naroxel bilang bahwa Courier Union akan mengirimkan orang.",
  ui_story_5009_50090602_9_dialog_content = "Mungkin itu adalah anggota serikat.",
  ui_story_5009_50090602_10_dialog_content = "Kalian sedang membahas apa, prajurit?",
  ui_story_5009_50090602_11_dialog_content = "Letnan Wakil, kami baru saja berbicara tentang bagaimana Eraveil melawan Eclipsites di masa lalu.",
  ui_story_5009_50090602_12_dialog_content = "Ada garis Illumina yang tidak bisa ditembus antara Eraveil dan bekas sarang Eclipsite.",
  ui_story_5009_50090602_13_dialog_content = "Medan Eraveil yang sulit membuatnya mudah untuk dipertahankan dan sulit untuk diserang musuh.",
  ui_story_5009_50090602_14_dialog_content = "Tapi, kaum Caelestite tak bisa bertarung. Apa yang terjadi saat mereka harus bertahan dari serangan Eclipsite?",
  ui_story_5009_50090602_15_dialog_content = "Mereka bisa merasakan pergerakan Eclipsite dan menyusun rencana duluan.",
  ui_story_5009_50090602_16_dialog_content = "Illumina dan Lumopolis sering mengutus wakil serta perbekalan ke Eraveil.",
  ui_story_5009_50090602_17_dialog_content = "Ya, Eraveil memang tak mudah dikalahkan.",
  ui_story_5009_50090602_18_dialog_content = "Tapi, sekali berhasil diserang, tamatlah riwayatnya.",
  ui_story_5009_50090602_19_dialog_content = "Aku yakin kau pasti sudah tahu kelanjutan ceritanya.",
  ui_story_5009_50090602_20_dialog_content = "Bagaimana para Eclipsite itu bisa menembus pertahanan Illumina dan masuk ke Eraveil?",
  ui_story_5009_50090602_21_dialog_content = "Ada pengkhianat di tengah kami.",
  ui_story_5009_50090602_22_dialog_content = "Makin kokoh pertahanan, makin mudah untuk dihancurkan oleh pengkhianat.",
  ui_story_5009_50090602_23_dialog_content = "Lagi pula, hari itu terjadi gerhana sehingga semua sistem pertahanan mati.",
  ui_story_5009_50090701_1_dialog_content = "Apa hanya perasaanku saja, atau memang tiba-tiba saja jadi gelap?",
  ui_story_5009_50090701_2_dialog_content = "Ini seharusnya siang hari, namun gelap seperti malam.",
  ui_story_5009_50090701_3_dialog_content = "Gerhana tepat seperti yang saya sebutkan? Bagaimana ini bisa terjadi?",
  ui_story_5009_50090701_4_dialog_content = "Tapi, dilihat dari cincin cahaya merah membara di langit itu, memang tidak salah lagi!",
  ui_story_5009_50090701_5_dialog_content = "Ini pasti fenomena yang mirip, pasti!",
  ui_story_5009_50090701_6_dialog_content = "Hati-hati, semuanya, saya merasakan gangguan aneh!",
  ui_story_5009_50090701_7_dialog_content = "Eraveil, gerhana...",
  ui_story_5009_50090701_8_dialog_content = "Apakah ini takdir Caelestite yang tak terelakkan?",
  ui_story_5009_50090701_9_dialog_content = "Tetap tenang, PlayerName!",
  ui_story_5009_50090701_10_dialog_content = "Berhenti berpikir berlebihan dan fokuslah pada saat ini.",
  ui_story_5009_50090701_11_dialog_content = "Kau benar. Aku baik-baik saja sekarang.",
  ui_story_5009_50090701_12_dialog_content = "Tapi, mungkinkah ini orang yang tadi kurasakan keberadaannya itu, siapa pun dia?",
  ui_story_5009_50090701_13_dialog_content = "Yang memiliki kemampuan penyembunyian?",
  ui_story_5009_50090701_14_dialog_content = "Langit gelap, korona merah.",
  ui_story_5009_50090701_15_dialog_content = "Kau baru saja mau ambil tindakan...",
  ui_story_5009_50090701_16_dialog_content = "Tapi, kali ini aku tak akan memberimu ampun!",
  ui_story_5009_50090702_1_dialog_content = "Apa yang terjadi?!",
  ui_story_5009_50090702_2_dialog_content = "Gah!",
  ui_story_5009_50090702_3_dialog_content = "Jangan panik! Bunuh Eclipsite dulu!",
  ui_story_5009_50090702_4_dialog_content = "Aku entah bagaimana... tidak bisa menggunakan kekuatan penuhku, Carleen...",
  ui_story_5009_50090702_5_dialog_content = "Aku juga merasa seperti itu.",
  ui_story_5009_50090702_6_dialog_content = "Bagaimana denganmu, PlayerName?",
  ui_story_5009_50090702_7_dialog_content = "Tak ada yang aneh, tapi...",
  ui_story_5009_50090702_8_dialog_content = "Hanya apa?",
  ui_story_5009_50090702_9_dialog_content = "Rasanya seakan-akan kemampuan psikisku tiba-tiba terputus begitu saja. Aku tak bisa merasakan apa pun yang jaraknya jauh.",
  ui_story_5009_50090702_10_dialog_content = "Luminatics kami juga teredam.",
  ui_story_5009_50090702_11_dialog_content = "Jika saya tidak salah, itu karena gerhana.",
  ui_story_5009_50090702_12_dialog_content = "Tetap siaga dan waspadai serangan dari para Eclipsite!",
  ui_story_5009_50090702_13_dialog_content = "Saya prihatin dengan grup di pos... Biar saya coba hubungi mereka.",
  ui_story_5009_50090702_14_dialog_content = "Sama sekali tak bisa menghubungi mereka!",
  ui_story_5009_50090702_15_dialog_content = "Jadi komunikasi juga terputus.",
  ui_story_5009_50090702_16_dialog_content = "Apa kita bisa bertemu dengan Naroxel di kantor pos?",
  ui_story_5009_50090702_17_dialog_content = "Biar kupimpin.",
  ui_story_5009_50090702_18_dialog_content = "Aku tidak bisa merasakan apa yang terjadi dari jarak ini, aku khawatir Eclipsites akan mengelilingi kita...",
  ui_story_5009_50090702_19_dialog_content = "Kami akan melindungi kalian, Lt. Vice.",
  ui_story_5009_50090702_20_dialog_content = "Baik, lakukan.",
  ui_story_5009_50090702_21_dialog_content = "Ayo, PlayerName!",
  ui_story_5009_50090801_1_dialog_content = "Ada ledakan yang datang!",
  ui_story_5009_50090801_2_dialog_content = "Awas!",
  ui_story_5009_50090801_3_dialog_content = "Awas!",
  ui_story_5009_50090801_4_dialog_content = "Sayang sekali, rupanya meleset.",
  ui_story_5009_50090801_5_dialog_content = "Kau sudah siap?",
  ui_story_5009_50090801_6_dialog_content = "Aku datang untuk mencarimu.",
  ui_story_5009_50090801_7_dialog_content = "Apa kalian semua baik-baik saja?",
  ui_story_5009_50090801_8_dialog_content = "Aku baik-baik saja. Bagaimana denganmu, PlayerName?",
  ui_story_5009_50090801_9_dialog_content = "Aku baik-baik saja.",
  ui_story_5009_50090801_10_dialog_content = "Sekarang aku sudah terbiasa.",
  ui_story_5009_50090801_11_dialog_content = "Di mana kita...?",
  ui_story_5009_50090801_12_dialog_content = "PlayerName, kau tahu ada tempat aneh semacam ini di Eraveil?",
  ui_story_5009_50090801_13_dialog_content = "Aku tak tahu. Aku hanya merasakan keanehan, kemampuan psikisku...",
  ui_story_5009_50090801_14_dialog_content = "Apakah apa? Apakah kamu terluka?",
  ui_story_5009_50090801_15_dialog_content = "Sama sekali tidak. Hanya saja... perasaan ini sulit untuk dijelaskan, seperti... seperti...",
  ui_story_5009_50090801_16_dialog_content = "Seperti hidungku penuh!",
  ui_story_5009_50090801_17_dialog_content = "Ini bukan saatnya bercanda!",
  ui_story_5009_50090801_18_dialog_content = "Maaf, tapi ini benar-benar yang saya rasakan.",
  ui_story_5009_50090801_19_dialog_content = "Tidak seperti sebelumnya, kali ini aku sama sekali tak bisa menggunakan kekuatanku.",
  ui_story_5009_50090801_20_dialog_content = "Kalau kita tidak bisa mengandalkan kemampuan PlayerName...",
  ui_story_5009_50090801_21_dialog_content = "Kita harus sangat hati-hati saat bertarung.",
  ui_story_5009_50090801_22_dialog_content = "Awas, Yang Mulia!",
  ui_story_5009_50090801_23_dialog_content = "!!!",
  ui_story_5009_50090801_24_dialog_content = "Sayang sekali, nyaris saja aku berhasil merengkuhmu...",
  ui_story_5009_50090801_25_dialog_content = "Yang Mulia, Carleen.",
  ui_story_5009_50090801_26_dialog_content = "Siapa kau?",
  ui_story_5009_50090801_27_dialog_content = "Aku merasa terhormat karena kau menanyakan namaku!",
  ui_story_5009_50090801_28_dialog_content = "Aku...",
  ui_story_5009_50090801_A1_dialog_content = "Oh, sepertinya aku sudah lupa siapa diriku.",
  ui_story_5009_50090801_29_dialog_content = "...",
  ui_story_5009_50090801_30_dialog_content = "Tidak ada reaksi?",
  ui_story_5009_50090801_31_dialog_content = "Anda seharusnya berteriak, \"Lelucon macam apa ini?\" atau \"Katakan padaku siapa kamu!\" di bagian atas paru-paru Anda pada saat seperti ini.",
  ui_story_5009_50090801_32_dialog_content = "Menjengkelkan sekali.",
  ui_story_5009_50090801_33_dialog_content = "Jangan buang-buang waktu lagi, Carleen.",
  ui_story_5009_50090801_34_dialog_content = "Bunuh saja dia!",
  ui_story_5009_50090801_35_dialog_content = "Aku sudah mencobanya, Vice, tapi kemampuan psikisku belum kembali normal.",
  ui_story_5009_50090801_36_dialog_content = "Bukan masalah. Biar kami saja yang bertarung!",
  ui_story_5009_50090801_37_dialog_content = "Vice, Pittman, lindungi aku.",
  ui_story_5009_50090801_38_dialog_content = "Kau mau melawanku?",
  ui_story_5009_50090801_39_dialog_content = "Oh, aku tak sabar!",
  ui_story_5009_50090801_40_dialog_content = "Kemarilah, Yang Mulia Carleen!",
  ui_story_5009_50090801_41_dialog_content = "Ice Blossom!",
  ui_story_5009_50090801_42_dialog_content = "Hmm...",
  ui_story_5009_50090801_43_dialog_content = "Kok tak terasa sakit sama sekali, ya?",
  ui_story_5009_50090801_44_dialog_content = "Ayo bertarung bersama, Carleen!",
  ui_story_5009_50090801_45_dialog_content = "Ah, pertarungan seperti ini...",
  ui_story_5009_50090801_46_dialog_content = "Sama sekali tidak artistik!",
  ui_story_5009_50090801_47_dialog_content = "!!!",
  ui_story_5009_50090801_48_dialog_content = "Kalian semua dipukuli dengan mudah.",
  ui_story_5009_50090801_49_dialog_content = "Kalian sama sekali bukan tandinganku!",
  ui_story_5009_50090801_50_dialog_content = "Apa maksudmu?",
  ui_story_5009_50090801_51_dialog_content = "Shh, jangan menyela. Kau membuatku kecewa, Carleen.",
  ui_story_5009_50090801_52_dialog_content = "Cara bertarungmu jelek dan tak pantas untuk seorang putri.",
  ui_story_5009_50090801_53_dialog_content = "Padahal tadinya aku berniat melukismu dengan indah, tapi sekarang aku jadi tak tertarik sama sekali.",
  ui_story_5009_50090801_54_dialog_content = "Semua itu salahmu. Impian Gautier jadi buyar.",
  ui_story_5009_50090801_55_dialog_content = "Lebih cantik? Nama keluarga yang terhapus dari catatan?",
  ui_story_5009_50090801_56_dialog_content = "Selain Beryl Gautier, hanya ada...",
  ui_story_5009_50090801_57_dialog_content = "Kau pasti Mirren Gautier!",
  ui_story_5009_50090801_58_dialog_content = "Wow, ternyata ada yang mengenaliku?",
  ui_story_5009_50090801_59_dialog_content = "Kau sudah lama masuk dalam daftar hitamku. Tak kusangka sekarang akhirnya aku bisa bertemu denganmu.",
  ui_story_5009_50090801_60_dialog_content = "Kau adalah pengungsi dan pengkhianat!",
  ui_story_5009_50090801_61_dialog_content = "Jangan marah-marah begitu! Setidaknya, tidak sebelum berterima kasih karena aku memberitahukan namaku!",
  ui_story_5009_50090801_62_dialog_content = "Mirren Gautier?",
  ui_story_5009_50090801_63_dialog_content = "Ya, Yang Mulia, Mirren dari House Gautier, dalang di balik pemberontakan Pylos dan Gautier!",
  ui_story_5009_50090801_64_dialog_content = "Jadi, dia dari Lumopolis?",
  ui_story_5009_50090801_65_dialog_content = "Penampilannya sekarang, dia terlihat aneh bahkan menurut standar Eclipsite.",
  ui_story_5009_50090801_66_dialog_content = "Pengkhianat Lumopolis dan Aurorian lainnya...",
  ui_story_5009_50090801_67_dialog_content = "Terimalah hukumanmu, Mirren Gautier!",
  ui_story_5009_50090801_68_dialog_content = "Kuharap kau tak hanya omong kosong belaka.",
  ui_story_5009_50090801_69_dialog_content = "Aku akan menahannya, kamu pergi mencari jalan keluar, PlayerName!",
  ui_story_5009_50090801_70_dialog_content = "Semua orang mengikuti PlayerName. Aku akan menutupi bagian belakang.",
  ui_story_5009_50090801_71_dialog_content = "Eh, kalian mau ke mana?",
  ui_story_5009_50090801_72_dialog_content = "Fooey, mereka lepas landas...",
  ui_story_5009_50090801_73_dialog_content = "Terimalah hukumanmu, dasar pendosa!",
  ui_story_5009_50090801_74_dialog_content = "Upaya Anda sia-sia. Apakah Anda pikir serangan lemah seperti itu akan berpengaruh pada saya?",
  ui_story_5009_50090801_75_dialog_content = "Ini konyol.",
  ui_story_5009_50090801_76_dialog_content = "Aku sudah memutuskan akan membuatmu sengsara sampai mati, lalu akan kubuat mereka merasakan hal yang sama.",
  ui_story_5009_50090801_77_dialog_content = "Tapi izinkan saya menawarkan beberapa saran ramah terlebih dahulu ...",
  ui_story_5009_50090801_78_dialog_content = "Bocah Caelestite tengil tak berguna itu tak akan bisa menemukan jalan keluar dari sini.",
  ui_story_5009_50090801_79_dialog_content = "Inilah kekuatan Eclipse!",
  ui_story_5009_50090801_80_dialog_content = "Saya melihat kaki Anda bukan satu-satunya hal yang menjadi kacau selama proses transformasi...",
  ui_story_5009_50090801_81_dialog_content = "tapi bola mata dan kepalamu juga!",
  ui_story_5009_50090801_82_dialog_content = "Hahahaha, baiklah. Tubuhmu yang akan segera kacau!",
  ui_story_5009_50090801_83_dialog_content = "Vice, Carleen, kurasa kita sudah sampai di ujung!",
  ui_story_5009_50090801_84_dialog_content = "Ya, aku bisa merasakan ada tembok yang tak kasat mata.",
  ui_story_5009_50090801_85_dialog_content = "Minggirlah, PlayerName.",
  ui_story_5009_50090801_86_dialog_content = "Hantam titik yang sama serentak bersamaku, Vice.",
  ui_story_5009_50090801_87_dialog_content = "Roger! Torrent Cepat!",
  ui_story_5009_50090801_88_dialog_content = "Jelas-jelas kita berhasil mengenainya, tapi tak ada tanda kerusakan sama sekali.",
  ui_story_5009_50090801_89_dialog_content = "Cari apa pun yang tampak janggal di sekitar sini. Bisa jadi itulah jalan keluarnya.",
  ui_story_5009_50090801_90_dialog_content = "Tidak, tak ada apa pun.",
  ui_story_5009_50090801_91_dialog_content = "Memangnya benar ada jalan keluar di dimensi aneh ini?",
  ui_story_5009_50090801_92_dialog_content = "Sial...",
  ui_story_5009_50090801_93_dialog_content = "Aku bisa merasakan semua hal lainnya seperti biasa, bahkan bisa mendengar suara mereka sedang bertarung.",
  ui_story_5009_50090801_94_dialog_content = "Tapi, kekuatan psikisku tak mau berfungsi!",
  ui_story_5009_50090801_95_dialog_content = "Aku takut Pittman tak akan bisa bertahan lama sendirian. Jika terus begini...",
  ui_story_5009_50090801_96_dialog_content = "Apa, cuma ini kemampuanmu?",
  ui_story_5009_50090801_97_dialog_content = "Mana Pittman?",
  ui_story_5009_50090801_98_dialog_content = "Bagaimana mungkin kau berharap bisa mengalahkanku dengan kekuatan sepayah itu?",
  ui_story_5009_50090801_99_dialog_content = "Oh, itu dia, tertatih-tatih menuju kemari. Lucu sekali, ya?",
  ui_story_5009_50090801_100_dialog_content = "Kau terluka, Pittman!",
  ui_story_5009_50090801_101_dialog_content = "Uhuk... Aku masih bisa bertarung... Jangan khawatir...",
  ui_story_5009_50090801_102_dialog_content = "Bagus sekali!",
  ui_story_5009_50090801_103_dialog_content = "Nah, kita lanjutkan permainannya.",
  ui_story_5009_50090801_104_dialog_content = "Haha!",
  ui_story_5009_50090901_1_dialog_content = "Tracking Strike!",
  ui_story_5009_50090901_2_dialog_content = "Hah? Oh, kalau soal serangan diam-diam, aku...",
  ui_story_5009_50090901_3_dialog_content = "Akulah ahlinya.",
  ui_story_5009_50090901_4_dialog_content = "Aduh...",
  ui_story_5009_50090901_5_dialog_content = "Mirren masih bisa menggunakan Luminatics Lumopolis. Kenapa bisa begini?",
  ui_story_5009_50090901_6_dialog_content = "Bagaimana keadaanmu, Vice?",
  ui_story_5009_50090901_7_dialog_content = "Biar kucoba!",
  ui_story_5009_50090901_8_dialog_content = "Jangan bilang begitu hingga kau lebih mahir bertarung daripada mereka semua.",
  ui_story_5009_50090901_9_dialog_content = "Aku punya saran untukmu, Caelestite.",
  ui_story_5009_50090901_10_dialog_content = "Kau menyebabkan gerhana ini dan menjebak kami di dimensi imajiner.",
  ui_story_5009_50090901_11_dialog_content = "Oh, itu kemampuan luar biasa yang diberikan kepadaku oleh sang Master yang hebat. Dengan kemampuan itu, aku bebas berbuat semauku!",
  ui_story_5009_50090901_12_dialog_content = "Bla, bla, bla. Itu tak lebih dari sekadar transformasi, dan bukan hal baru bagi kami. Misalnya, Schummer...",
  ui_story_5009_50090901_13_dialog_content = "Oh, ternyata kau lucu, Caelestite kecil.",
  ui_story_5009_50090901_14_dialog_content = "Teman-teman Aurorian yang terhormat, kalian benar-benar berharap Caelestite ini bisa menyelamatkan kalian dengan omongan belaka?",
  ui_story_5009_50090901_15_dialog_content = "Kau terlalu banyak omong!",
  ui_story_5009_50090901_16_dialog_content = "Biar aku saja yang bertarung, PlayerName. Pergilah mencari jalan keluar.",
  ui_story_5009_50090901_17_dialog_content = "Eh, sebentar. Rupanya kalian masih belum sadar apa yang terjadi, ya?",
  ui_story_5009_50090901_18_dialog_content = "Ini duniaku.",
  ui_story_5009_50090901_19_dialog_content = "Kuingatkan untuk terakhir kalinya, sebaiknya tak usah berusaha melawanku di sini.",
  ui_story_5009_50090901_20_dialog_content = "Omong kosong!",
  ui_story_5009_50090901_21_dialog_content = "Ini Eraveil, dan ini bukan milikmu!",
  ui_story_5009_50090901_22_dialog_content = "Aku tak akan membiarkan kau berbuat seenak perutmu di sini!",
  ui_story_5009_50090901_23_dialog_content = "Sungguh? Bagaimana kalau kautunjukkan kemampuanmu?",
  ui_story_5009_50090901_24_dialog_content = "Kalau usahamu cukup memuaskan, akan kubiarkan kau mati dengan cepat.",
  ui_story_5009_50090901_25_dialog_content = "Nah, jangan bilang aku tak memberimu kesempatan! Bagaimana menurutmu, Carleen? Ups, maafkan kelancanganku.",
  ui_story_5009_50090901_26_dialog_content = "Tapi... Hmm...",
  ui_story_5009_50090901_27_dialog_content = "Aku harus memanggilmu apa? Yang Mulia atau Kapten?",
  ui_story_5009_50090901_28_dialog_content = "Kau tak pantas untuk menyebut kedua gelar itu!",
  ui_story_5009_50090901_29_dialog_content = "Kau, pengkhianat Light, pelanggar hukum Lumopolis... Uhuk, uhuk...",
  ui_story_5009_50090901_30_dialog_content = "Kau terluka, Pittman!",
  ui_story_5009_50090901_31_dialog_content = "Tak ada akhir baik bagi pengkhianat, Mirren Gautier.",
  ui_story_5009_50090901_32_dialog_content = "Tombakkulah yang akan menghabisimu.",
  ui_story_5009_50090901_33_dialog_content = "Waduh, aku minta maaf, Carleen, si tua perwujudan kebenaran!",
  ui_story_5009_50090901_34_dialog_content = "Aku sadar akan kesalahanku. Haruskah aku berlutut dan bertobat?",
  ui_story_5009_50090901_35_dialog_content = "Aku sama sekali tak sengaja, sungguh... Hee!",
  ui_story_5009_50090901_36_dialog_content = "Mampuslah kau, Mirren Gautier!",
  ui_story_5009_50090901_37_dialog_content = "Gautier, Gautier, Gautier...",
  ui_story_5009_50090901_38_dialog_content = "Kenapa nama ini terdengar sangat tak menyenangkan saat keluar dari mulutmu?",
  ui_story_5009_50090901_39_dialog_content = "Gautier adalah nama belakang bangsawan yang diturunkan dari generasi ke generasi di Lumopolis. Kau tak pantas menyandang nama itu!",
  ui_story_5009_50090901_40_dialog_content = "Terhormat? Sudah lama keluarga Gautier selalu berada di bawah keluarga Schwartz... Bukan, maksudku di bawah nama Lumopolis.",
  ui_story_5009_50090901_41_dialog_content = "Kaulah yang dulu telah menghancurkan orang-orangku, nama kami, kejayaan kami...",
  ui_story_5009_50090901_42_dialog_content = "Omong kosong!",
  ui_story_5009_50090901_43_dialog_content = "Lumopolis memperlakukan keluarga Gautier dan Pyrrhus dengan sangat hati-hati semenjak adanya pemberontakan itu.",
  ui_story_5009_50090901_44_dialog_content = "Sampai akhirnya mereka terpaksa mengambil langkah ekstrem.",
  ui_story_5009_50090901_45_dialog_content = "Memang sudah sepantasnya begitu untukmu.",
  ui_story_5009_50090901_46_dialog_content = "Itukah yang kaubaca dari buku pelajaranmu, Putri yang terhormat?",
  ui_story_5009_50090901_47_dialog_content = "Aku tak kaget, sih, karena sama halnya denganmu, sejarah Lumopolis...",
  ui_story_5009_50090901_48_dialog_content = "Mudah dipelintir oleh orang lain.",
  ui_story_5009_50090901_49_dialog_content = "Jangan buang-buang waktu kita untuk begundal ini, Yang Mulia.",
  ui_story_5009_50090901_50_dialog_content = "Lebih tepatnya, dalang pemberontakan sekaligus seorang buronan.",
  ui_story_5009_50090901_51_dialog_content = "Yang benar saja, Yang Mulia! Kaukira kau masih bisa sok suci seperti saat di persidangan?",
  ui_story_5009_50090901_52_dialog_content = "Apa kau juga ingin aku berlutut dan bertobat?",
  ui_story_5009_50090901_53_dialog_content = "Kau terlalu banyak omong, Mirren!",
  ui_story_5009_50090901_54_dialog_content = "Mungkin saja dia sudah memendamnya terlalu lama dan menunggu sampai bisa meluapkannya.",
  ui_story_5009_50090901_55_dialog_content = "Kedengarannya dia seperti orang jahat yang mendapatkan perlakuan salah. Tapi, di mana ya aku pernah melihatnya...?",
  ui_story_5009_50090901_56_dialog_content = "Meluapkan? Diperlakukan salah? Tidak, tidak, tidak.",
  ui_story_5009_50090901_57_dialog_content = "Tapi, tak lama lagi anggota keluarga Gautier yang diperlakukan buruk dan dibunuh oleh Lumopolis mestinya bisa meluapkan amarah mereka kepadamu.",
  ui_story_5009_50090901_58_dialog_content = "Simpan untuk Carleen kita yang mulia, kalian semua harus mati.",
  ui_story_5009_50090901_59_dialog_content = "Dasar pengkhianat tak punya malu! Kaulah yang menyulut pemberontakan itu! Kaulah pembunuh yang sebenarnya!",
  ui_story_5009_50090901_60_dialog_content = "Itukah kesimpulan atau putusannya, Yang Mulia?",
  ui_story_5009_50090901_61_dialog_content = "Heh, keputusan tak berarti tanpa kuasa sejati.",
  ui_story_5009_50090901_62_dialog_content = "Kau bisa menanyakan kebenarannya kepada orang-orangku setelah kau mati.",
  ui_story_5009_50090901_63_dialog_content = "Nah, sekarang, akan kuberi kalian...",
  ui_story_5009_50090901_64_option_content = "Ada ledakan!",
  ui_story_5009_50090901_65_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5009_50090901_66_dialog_content = "Apa-apaan...?",
  ui_story_5009_50090901_67_dialog_content = "Hancurkan!",
  ui_story_5009_50090901_68_dialog_content = "Aduh!",
  ui_story_5009_50090901_69_dialog_content = "Apa kalian semua baik-baik saja?",
  ui_story_5009_50090901_70_dialog_content = "Aku di sini, PlayerName. Semuanya baik-baik saja.",
  ui_story_5009_50090901_71_dialog_content = "Kita berhasil keluar!",
  ui_story_5009_50090901_72_dialog_content = "Luminatics-mu benar-benar luar biasa, Kapten Carleen.",
  ui_story_5009_50090901_73_dialog_content = "Tadi itu bukan aku.",
  ui_story_5009_50090901_74_dialog_content = "Tetap waspada, kita masih dalam pengaruh gerhana.",
  ui_story_5009_50090901_75_dialog_content = "Apa katamu barusan, PlayerName?",
  ui_story_5009_50090901_76_dialog_content = "Aku merasakan keberadaan Aurorian yang tadi ada di pemakaman.",
  ui_story_5009_50090901_77_dialog_content = "Jadi, Aurorian yang di pertempuran barusan...",
  ui_story_5009_50090901_78_dialog_content = "Benar! Ledakan energi yang tiba-tiba barusan pasti berasal dari Aurorian yang sama!",
  ui_story_5009_50090901_79_dialog_content = "Energi itu menembus pembatas dimensi dan menghantam Mirren.",
  ui_story_5009_50090901_80_dialog_content = "Baru sekali ini kulihat serangan sekuat itu. Aurorian itu punya kekuatan samaran dan penghancur yang luar biasa!",
  ui_story_5009_50090901_81_dialog_content = "Kau juga belum pernah melihat Luminatics sekuat itu?",
  ui_story_5009_50090901_82_dialog_content = "Heh, tak kusangka aku akan dipuji oleh Lady Carleen!",
  ui_story_5009_50090901_83_dialog_content = "Siapa kau?",
  ui_story_5009_50090901_84_dialog_content = "Uhuk... Rupanya kaulah orangnya.",
  ui_story_5009_50090901_85_dialog_content = "Biar kuperkenalkan. Nona ini berasal dari Church of Lumopolis...",
  ui_story_5009_50090901_86_dialog_content = "Bukan, maksudku, dari True Order, Paloma Py...",
  ui_story_5009_50090901_87_dialog_content = "Paloma Pyrrhus? Dari House Pyrrhus?",
  ui_story_5009_50090901_88_dialog_content = "Kau memang cermat dan teliti, Yang Mulia!",
  ui_story_5009_50090901_89_dialog_content = "Tidakkah kau gembira bisa bertemu dengan dua penjahat buron dari dua keluarga pemberontak sekaligus dalam sehari?",
  ui_story_5009_50090901_90_dialog_content = "Kau Paloma Pyrrhus? Mana mungkin kau ini anggota keluarga Pyrrhus? Kukira Caroline...",
  ui_story_5009_50090901_91_dialog_content = "Panggil aku Paloma, Yang Mulia.",
  ui_story_5009_50090901_92_dialog_content = "Rupanya kau, Paloma! Kau sudah banyak berubah.",
  ui_story_5009_50090901_93_dialog_content = "Baiklah, sekarang aku jadi benar-benar bingung...",
  ui_story_5009_50090901_94_dialog_content = "House Pyrrhus dan House Gautier adalah sesama rekan konspirator, PlayerName, dan itu berarti si Paloma ini...",
  ui_story_5009_50090901_95_dialog_content = "Jangan lupa, Yang Mulia.",
  ui_story_5009_50090901_96_dialog_content = "Paloma bukan hanya anggota House Pyrrhus yang memberontak, tetapi dia juga seorang biarawati yang meninggalkan Light.",
  ui_story_5009_50090901_97_dialog_content = "Kalau aku tak salah, dia juga termasuk dalam daftar hitam buronanmu, 'kan? Bukankah harusnya kau menangkapnya, wahai kesatria bajik?",
  ui_story_5009_50090901_98_dialog_content = "Cara Lumopolis menegakkan hukumnya bukanlah urusanmu.",
  ui_story_5009_50090901_99_dialog_content = "Membosankan sekali mendengar kalian mengoceh.",
  ui_story_5009_50090901_100_dialog_content = "Mirren Gautier harus mati. Selain itu, aku tak peduli.",
  ui_story_5009_50090901_101_dialog_content = "Aku tahu Mirren memulai semua ini sendirian!",
  ui_story_5009_50090901_102_dialog_content = "Tapi, bagaimana House Pyrrhus bisa terlibat?",
  ui_story_5009_50090901_103_dialog_content = "Kau bisa terus bertanya sesukamu, Yang Mulia.",
  ui_story_5009_50090901_104_dialog_content = "Aku kemari untuk balas dendam, bukan untuk mengumpulkan informasi.",
  ui_story_5009_50090901_105_dialog_content = "Oh, mengharukan sekali saat kawan lama bertemu kembali.",
  ui_story_5009_50090901_106_dialog_content = "Berapa kali harus kubilang kepadamu, Paloma? Orang-orang berkuasa di Lumopolis itulah yang membunuh orang-orangmu!",
  ui_story_5009_50090901_107_dialog_content = "Yang harusnya kaukejar justru si Carleen Schwartz yang arogan dan congkak ini!",
  ui_story_5009_50090901_108_dialog_content = "Tentu saja, si hakim terhormat itu juga.",
  ui_story_5009_50090901_109_dialog_content = "Sepertinya kita punya pemahaman berbeda tentang arti kata \"dalang\".",
  ui_story_5009_50090901_110_dialog_content = "Tapi, yah, memang kita tak bisa berharap bahwa Eclipsite akan bisa sepenuhnya memahami bahasa Aurorian.",
  ui_story_5009_50090901_111_dialog_content = "Jangan menghinaku!",
  ui_story_5009_50090901_112_dialog_content = "Ini kesempatan terakhirmu.",
  ui_story_5009_50090901_113_dialog_content = "Balaskan dendammu terhadap Lumopolis bersamaku, atau matilah bersama mereka. Pilih salah satu.",
  ui_story_5009_50090901_114_dialog_content = "Kurasa hanya kematianlah yang bisa mengobati omong kosongmu.",
  ui_story_5009_50090901_115_dialog_content = "Mengobati? Sebenarnya justru mencerahkanku, karena kau sebenarnya tak perlu mati.",
  ui_story_5009_50090901_116_dialog_content = "Masterku yang hebat pasti akan senang kalau aku membawakan mainan baru untuknya.",
  ui_story_5009_50090901_117_dialog_content = "Seorang wanita Aurorian yang kuat dan cantik.",
  ui_story_5009_50090901_118_dialog_content = "Hmm. Coba saja.",
  ui_story_5009_50090901_119_dialog_content = "Ada apa ini? Apa si Paloma itu membantu kita bertarung?",
  ui_story_5009_50090901_120_dialog_content = "Dia kuat. Mirren mungkin tak akan menang melawannya.",
  ui_story_5009_50090901_121_dialog_content = "Paloma termasuk salah satu orang paling berbahaya di gereja. Dia sudah memalingkan diri sepenuhnya dari Light dan bergabung dengan True Order.",
  ui_story_5009_50090901_122_dialog_content = "True Order... Sepertinya Paloma berhasil mempelajari Luminatics istimewa dari mereka.",
  ui_story_5009_50090901_123_dialog_content = "Luminatics yang tak terpengaruh oleh gerhana ini, bahkan sanggup menembus pembatas dimensi.",
  ui_story_5009_50090901_124_dialog_content = "Sebentar, kurasa percakapan antara Paloma dan Eclipsite itu adalah tentang...",
  ui_story_5009_50090901_125_dialog_content = "Hei, kau mau berhenti mengoceh tidak?",
  ui_story_5009_50090901_126_dialog_content = "Bala bantuan Mirren sedang menuju kemari, dan aku kemari bukan untuk menjaga kalian!",
  ui_story_5009_50090901_127_dialog_content = "Ice Blossom! Menyebar!",
  ui_story_5009_50090901_128_dialog_content = "Oh tidak, aku merasakan para Eclipsite mendekat ke arah kita...",
  ui_story_5009_50090901_129_dialog_content = "Tak apa, bala bantuan kita juga sudah sampai di sini!",
  ui_story_5009_50090901_130_dialog_content = "Apa kau masih bisa memandu koordinasi, PlayerName?",
  ui_story_5009_50090901_131_dialog_content = "Bisa!",
  ui_story_5009_50090902_1_dialog_content = "Apa kita sungguh akan bertarung, Lady Pyrrhus?",
  ui_story_5009_50090902_2_dialog_content = "Mengulang-ulang kalimat yang sama, Tuan Gautier?",
  ui_story_5009_50090902_3_dialog_content = "Ini berbeda, melihat dua orang pengkhianat Lumopolis bertarung di hadapan penguasanya.",
  ui_story_5009_50090902_4_dialog_content = "Menurutmu, siapa yang akan paling diuntungkan?",
  ui_story_5009_50090902_5_dialog_content = "Aku punya banyak waktu untuk memikirkannya setelah kau mati.",
  ui_story_5009_50090902_6_dialog_content = "Kita justru saling melemahkan dan membuat mereka bisa menegakkan sesuatu yang disebut keadilan pada akhirnya. Bagus.",
  ui_story_5009_50090902_7_dialog_content = "Kalau kita mati, berakhir sudah garis keturunan Gautier dan Pyrrhus!",
  ui_story_5009_50090902_8_dialog_content = "Kita berdua sama-sama sudah merasakan keadilan versi Lumopolis, Paloma.",
  ui_story_5009_50090902_9_dialog_content = "Perbuatan keluarga Pyrrhus mencoreng muka Lumopolis. Mohon ampuni kami, God of Light.",
  ui_story_5009_50090902_10_dialog_content = "Kami bersedia menerima hukuman asalkan kau mau mengampuni kami.",
  ui_story_5009_50090902_11_dialog_content = "Rasa sakit akibat kehilangan Luminatics akan selalu mengingatkanku untuk tidak berbuat jahat...",
  ui_story_5009_50090902_12_dialog_content = "<color=#e8d9bb>Tok, tok!</color>",
  ui_story_5009_50090902_13_dialog_content = "Exile Settlement 14, apa ada orang di dalam? Aku utusan dari Lumopolis.",
  ui_story_5009_50090902_14_dialog_content = "Buka pintunya dan tanda tangani suratnya, Paloma.",
  ui_story_5009_50090902_15_dialog_content = "Baik, Ayah.",
  ui_story_5009_50090902_16_dialog_content = "<color=#e8d9bb>Kriek...</color>",
  ui_story_5009_50090902_17_dialog_content = "Dalam setahun terakhir ini, kehidupan di Lower Lumopolis membuat kita semua merasa sengsara.",
  ui_story_5009_50090902_18_dialog_content = "Jelas-jelas ini akibat kesalahan mereka, kenapa kita juga harus ikut menderita?",
  ui_story_5009_50090902_19_dialog_content = "Aku tak keberatan kalau hanya kita berdua yang harus sengsara, tapi anak kita...",
  ui_story_5009_50090902_20_dialog_content = "Memangnya kenapa? Kemungkinan terburuknya adalah kita meninggalkan gereja, kehilangan Luminatics, dan hidup seperti rakyat jelata.",
  ui_story_5009_50090902_21_dialog_content = "Tapi, menculik anak-anak Gautier untuk diubah bukanlah sekadar kesalahan, tapi dosa besar.",
  ui_story_5009_50090902_22_dialog_content = "Tapi... Tapi, apa hubungannya dengan kita?",
  ui_story_5009_50090902_23_dialog_content = "Keluarga Schwartz tak pernah peduli dengan keluarga bangsawan lain.",
  ui_story_5009_50090902_24_dialog_content = "Diamlah!",
  ui_story_5009_50090902_25_dialog_content = "Tahu tidak, bahkan anggota keluarga Gautier yang tak bersalah pun sudah diusir ke Lower Lumopolis?",
  ui_story_5009_50090902_26_dialog_content = "Apa? Apa yang terjadi?",
  ui_story_5009_50090902_27_dialog_content = "Pasrah sajalah kepada nasib. Bersyukurlah karena kita masih hidup.",
  ui_story_5009_50090902_28_dialog_content = "...",
  ui_story_5009_50090902_29_dialog_content = "Ayah, Ibu, apa kalian kenal Mirren Gautier?",
  ui_story_5009_50090902_30_dialog_content = "Mirren?",
  ui_story_5009_50090902_31_dialog_content = "Bukankah dia pelukis dari House Gautier yang termasyhur itu?",
  ui_story_5009_50090902_32_dialog_content = "Kenapa kau menanyakannya, Paloma?",
  ui_story_5009_50090902_33_dialog_content = "Kita baru saja mendapat surat pemberitahuan dari Hall of Justice. Di sini tertulis bahwa Mirren Gautier adalah ancaman.",
  ui_story_5009_50090902_34_dialog_content = "Dia orang yang sangat berbahaya, dan kita harus segera memberi tahu pihak berwenang.",
  ui_story_5009_50090902_35_dialog_content = "Sungguh? Beberapa hari lalu, pamanmu menyebut tentangnya kepadaku.",
  ui_story_5009_50090902_36_dialog_content = "Waktu mengobrol kemarin, kakakku juga menyebut nama itu.",
  ui_story_5009_50090902_37_dialog_content = "Perasaanku tidak enak. Kita harus hati-hati.",
  ui_story_5009_50090902_38_dialog_content = "Aku paham, Yah...",
  ui_story_5009_50090902_39_dialog_content = "<color=#e8d9bb>Tok, tok!</color>",
  ui_story_5009_50090902_40_dialog_content = "Cepat, cepat...",
  ui_story_5009_50090902_41_dialog_content = "Lari, Lumopolis Army sudah mengepung permukiman ini!",
  ui_story_5009_50090902_42_dialog_content = "Apa?",
  ui_story_5009_50090902_43_dialog_content = "Tenang, santai saja, ya?",
  ui_story_5009_50090902_44_dialog_content = "Mirren dari House Gautier berusaha merebut kekuasaan. Dia berhasil mengerahkan pasukan sekaligus pihak gereja!",
  ui_story_5009_50090902_45_dialog_content = "House Gautier memberontak?",
  ui_story_5009_50090902_46_dialog_content = "Gereja? Kenapa pihak gereja ikut bereaksi?",
  ui_story_5009_50090902_47_dialog_content = "Sepertinya Mirren memanfaatkan transformasi, dan keluarga Pyrrhus serta para Eclipsite ikut terlibat dalam pemberontakan itu.",
  ui_story_5009_50090902_48_dialog_content = "Aku harus pergi. Kau juga harus lari.",
  ui_story_5009_50090902_49_dialog_content = "Apa hubungannya ini dengan kita?",
  ui_story_5009_50090902_50_dialog_content = "Kalau sudah paham kebiasaan di Lumopolis, ini akan berujung pada penganiayaan besar-besaran.",
  ui_story_5009_50090902_51_dialog_content = "Sebagai seorang Pyrrhus, kita tak perlu khawatir asalkan kita menjalani pemeriksaan secara adil.",
  ui_story_5009_50090902_52_dialog_content = "Kau terlalu idealis, Nak...",
  ui_story_5009_50090902_53_dialog_content = "Dengarkan aku, sembunyilah. Aku akan memeriksanya bersama ibumu.",
  ui_story_5009_50090902_54_dialog_content = "Ikutlah denganku sekarang, Paloma. Kalau menunggu lebih lama lagi, tak akan ada yang pergi.",
  ui_story_5009_50090902_55_dialog_content = "Sana!",
  ui_story_5009_50090902_56_dialog_content = "Sesuai keputusan dari Lord, bunuh para pengkhianat itu! Sesuai keputusan Lord, bunuh para pengkhianat itu!",
  ui_story_5009_50090902_57_dialog_content = "Kenapa mereka berkelahi, dan dari mana asal monster-monster itu...",
  ui_story_5009_50090902_58_dialog_content = "Hah?! Mereka semua itu orang-orang kita! Eclipsite... Mereka sudah berubah menjadi Eclipsite!",
  ui_story_5009_50090902_59_dialog_content = "Tamat sudah... Inilah akhir nasib keluarga kita.",
  ui_story_5009_50090902_60_dialog_content = "Hukum para pemberontak itu! Hukum para pemberontak itu! Hukum para pemberontak itu!",
  ui_story_5009_50090902_62_dialog_content = "Keadilan Lumopolis... Hah! Aku juga sudah banyak mengalaminya.",
  ui_story_5009_50090902_63_dialog_content = "*Batuk-batuk* Kalau begitu, cepatlah... Dan hentikan seranganmu...",
  ui_story_5009_50090902_64_dialog_content = "Semuanya berawal dari Lumopolis...",
  ui_story_5009_50090902_65_dialog_content = "Bagus sekali, Mirren Gautier. Begitu kau mati, akan kupastikan si wali kota juga ikut mati menemanimu.",
  ui_story_5009_50090902_66_dialog_content = "Tapi, kita urus yang penting dulu... Ini saatnya kau mati.",
  ui_story_5009_50090902_67_dialog_content = "Nona Paloma Pyrrhus... Kalau memang harus begini akhirnya, aku hanya ingin menguburmu bersama para prajurit bajik itu dengan layak.",
  ui_story_5009_50090902_68_dialog_content = "Kata-katamu masih saja berlebih-lebihan seperti biasanya...",
  ui_story_5009_50091001_1_dialog_content = "Sial... Kemampuan psikisku masih belum pulih sepenuhnya...",
  ui_story_5009_50091001_2_dialog_content = "Tak apa, PlayerName! Komando darimu barusan masih sangat tepat!",
  ui_story_5009_50091001_3_dialog_content = "Bagaimana dengan monsternya? Ke mana dia pergi?",
  ui_story_5009_50091001_4_dialog_content = "Dia masih di dekat sini! Tapi, sepertinya kekuatannya... Bertambah?",
  ui_story_5009_50091001_5_dialog_content = "Tapi, serangan dari Paloma tadi membuatnya cedera berat! Kita semua melihatnya! Kecuali...",
  ui_story_5009_50091001_6_dialog_content = "Sepertinya dia memangsa para Eclipsite di dekatnya untuk mengumpulkan kembali Darkflow-nya.",
  ui_story_5009_50091001_7_dialog_content = "Aduh... Jangan hal menjijikkan ini lagi, dong.",
  ui_story_5009_50091001_8_dialog_content = "Apa kaudengar itu, Paloma?",
  ui_story_5009_50091001_9_dialog_content = "Monster itu masih berkeliaran di dekat sini! Tetap waspada!",
  ui_story_5009_50091001_10_dialog_content = "Khawatirkan saja dirimu sendiri. Jangan menghalangiku.",
  ui_story_5009_50091001_11_dialog_content = "Gelombang Darkflow!!",
  ui_story_5009_50091001_12_dialog_content = "Gawat, asalnya dari arah Paloma! Monster itu menyerang!",
  ui_story_5009_50091001_13_dialog_content = "Ini buruk...",
  ui_story_5009_50091001_14_option_content = "Force Boost",
  ui_story_5009_50091001_15_dialog_content = "Paloma! Menghindar ke arah kiri depan!",
  ui_story_5009_50091001_16_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5009_50091001_17_dialog_content = "Kau... Kau baik-baik saja, Paloma?",
  ui_story_5009_50091001_18_dialog_content = "*Batuk-batuk* Inikah... kekuatan Caelestite?",
  ui_story_5009_50091001_19_dialog_content = "Langsung mengirimkan pikiran ke kepalaku...",
  ui_story_5009_50091001_20_dialog_content = "Bukankah harusnya kau minta izin dulu?",
  ui_story_5009_50091001_21_dialog_content = "Kalau bukan karena PlayerName menggunakan kekuatannya untuk membantumu menghindar...",
  ui_story_5009_50091001_22_dialog_content = "Serangan Mirren pasti sudah mengenaimu.",
  ui_story_5009_50091001_23_dialog_content = "Mirren... menyelinap dan menyerang seperti tikus.",
  ui_story_5009_50091001_24_dialog_content = "Hahaha! Aku suka sikapmu itu, nona kecil Illumina!",
  ui_story_5009_50091001_25_dialog_content = "Aku baik-baik saja, tak usah mengkhawatirkanku!",
  ui_story_5009_50091001_26_dialog_content = "Kita harus melakukan segala cara untuk menemukannya, sebelum dia kabur!",
  ui_story_5009_50091001_27_dialog_content = "\"Kalau tak bisa menyerang, kabur saja.\" Memang seperti itulah cara bertarung Mirren Gautier sejak dulu.",
  ui_story_5009_50091001_28_dialog_content = "Sepertinya kau sangat mengenalnya, Paloma.",
  ui_story_5009_50091001_29_dialog_content = "Hmm... Yang jelas, aku tahu bahwa caranya bertarung seperti pengecut.",
  ui_story_5009_50091002_1_dialog_content = "Keluarga Gautier dan Pyrrhus memberontak melawan penguasa dan berkomplot dengan Eclipsite! Jangan pernah lupakan pengkhianatan mereka!",
  ui_story_5009_50091002_2_dialog_content = "Hukum para pemberontak itu! Bantai para Eclipsite itu!",
  ui_story_5009_50091002_3_dialog_content = "Semuanya, tenanglah! Kami tak lebih dari sekadar anggota keluarga Pyrrhus! Tolong mengertilah!",
  ui_story_5009_50091002_4_dialog_content = "Keluarga kalian adalah pengkhiatan yang memberontak, dan bahkan berani bersekongkol dengan Eclipsite! Kalian tak pantas diberi ampun!",
  ui_story_5009_50091002_5_dialog_content = "Kalau ini ada hubungannya dengan eksperimen kristal itu... Kami sudah menerima hukuman atas perbuatan itu, Lord!",
  ui_story_5009_50091002_6_dialog_content = "Lumina kami direnggut, dan kami diusir ke Lower Lumopolis..",
  ui_story_5009_50091002_7_dialog_content = "Setiap hari kami berdoa kepada God of Light, memohon ampun... Aku bersumpah, aku bicara jujur!",
  ui_story_5009_50091002_8_dialog_content = "Orang-orang yang diubah menjadi Eclipsite itu... Mereka anggota keluarga Pyrrhus!",
  ui_story_5009_50091002_9_dialog_content = "Kami... Kami tidak seperti mereka...",
  ui_story_5009_50091002_10_dialog_content = "Kami tidak diubah!",
  ui_story_5009_50091002_A1_dialog_content = "Kalian bersalah, kalian semua! Guard! Tangkap mereka!",
  ui_story_5009_50091002_11_dialog_content = "Ayah! Ibu! Ada apa ini?",
  ui_story_5009_50091002_12_dialog_content = "Paloma...?! Lari, Paloma! Lari!!",
  ui_story_5009_50091002_13_dialog_content = "Ayah? Ibu...!",
  ui_story_5009_50091002_14_dialog_content = "Pluma... Ikutlah denganku, cepat!",
  ui_story_5009_50091002_15_dialog_content = "Aduh...",
  ui_story_5009_50091002_16_dialog_content = "Menjauhlah darinya!",
  ui_story_5009_50091002_17_dialog_content = "Apakah kamu gila, wanita ?! Beraninya kau menggigitku!",
  ui_story_5009_50091002_18_dialog_content = "Kalian semua! Kejar gadis itu!",
  ui_story_5009_50091002_19_dialog_content = "Siap, Pak!",
  ui_story_5009_50091002_20_dialog_content = "Pluma, kumohon... Kau harus makan sesuatu.",
  ui_story_5009_50091002_21_dialog_content = "Kenapa... Kenapa ini semua terjadi...?",
  ui_story_5009_50091002_22_dialog_content = "Ayah... Ibu... Apa mereka baik-baik saja?",
  ui_story_5009_50091002_23_dialog_content = "Sudah tiga hari, Paloma. Kau harus istirahat.",
  ui_story_5009_50091002_24_dialog_content = "Akhirnya kau kembali! Apa kaudengar kabar tentang orang tuaku?",
  ui_story_5009_50091002_25_dialog_content = "Aku... aku hanya dengar kabar buruk. Kalau kau ingin mendengarnya, kau harus menguatkan hatimu.",
  ui_story_5009_50091002_26_dialog_content = "Semua kerabat kita sudah dibantai oleh prajurit Lumopolis, bersama...",
  ui_story_5009_50091002_27_dialog_content = "......",
  ui_story_5009_50091002_28_dialog_content = "Pasti kau tahu apa yang kumaksud... Iya, 'kan?",
  ui_story_5009_50091002_29_dialog_content = "Aku tak tahu dari mana Mirren Gautier mempelajari teknik transformasi itu, tapi dia menculik sejumlah kerabat kita dan melakukan eksperimen kepada mereka.",
  ui_story_5009_50091002_30_dialog_content = "Tak lama setelah itu, keluarga Gautier mulai menjalankan aksi pemberontakan.",
  ui_story_5009_50091002_31_dialog_content = "Mereka mengubah... anggota keluarga kita? Apa mereka membalas dendam kepada keluarga Pyrrhus?",
  ui_story_5009_50091002_32_dialog_content = "Tidak semuanya. Mereka merasa mereka adalah korban, dan bahwa mereka semua diasingkan oleh penguasa yang sama.",
  ui_story_5009_50091002_33_dialog_content = "Kurasa, kebencian mereka terhadap kalangan bangsawan Lumopolis adalah salah satu faktor besar yang memantik pemberontakan mereka.",
  ui_story_5009_50091002_34_dialog_content = "Apa pun itu, pembantaian ini menjadi bukti bahwa lagi-lagi Lumopolis menjatuhkan hukuman yang tak adil. Bagi kalangan bangsawan, ini adalah jawaban paling menyeluruh bagi masalah mereka.",
  ui_story_5009_50091002_35_dialog_content = "Jadi, tak ada kebenaran atau keadilan sejati...?",
  ui_story_5009_50091002_36_dialog_content = "Kebenarannya... terlalu rumit, dan akan menodai reputasi kalangan bangsawan.",
  ui_story_5009_50091002_37_dialog_content = "Bagaimana dengan keadilan? Yah... Seluruh keluarga kita musnah. Menurut orang luar, INI keadilan.",
  ui_story_5009_50091002_38_dialog_content = "Lau, bagaimana dengan kita? Apa ini berarti kita tak bersalah?",
  ui_story_5009_50091002_39_dialog_content = "Takdir membiarkan kita selamat. Tak ada gunanya kalau kita terlalu memikirkannya.",
  ui_story_5009_50091002_40_dialog_content = "Tidak... Mestinya tidak seperti ini. Tak mungkin... Ini bukan keadilan, sama sekali bukan.",
  ui_story_5009_50091002_41_dialog_content = "Bagian paling buruknya adalah walaupun keluarga Gautier dan Pylos sudah dihabisi tanpa sisa, Mirren masih belum tertangkap.",
  ui_story_5009_50091002_42_dialog_content = "Mirren Gautier... Sekarang ini, usianya tak terlalu jauh di atasmu.",
  ui_story_5009_50091002_43_dialog_content = "Dulu, dia hanyalah bocah lelaki yang suka menggambar... Aku tak bisa membayangkan dari mana dia memperoleh pengetahuan seperti itu.",
  ui_story_5009_50091002_44_dialog_content = "Dia belum mati? Bagus... aku tahu apa yang harus kulakukan sekarang.",
  ui_story_5009_50091002_45_dialog_content = "Nah, sekarang coba pikirkan tentang orang tuamu. Mereka pasti ingin kau hidup bahagia.",
  ui_story_5009_50091002_46_dialog_content = "Ibu... Ayah...",
  ui_story_5009_50091002_47_dialog_content = "Apa kau sudah lupa? Mengalahkan prajurit rendahan saja sekarang kau tidak bisa.",
  ui_story_5009_50091002_48_dialog_content = "Maksudmu, tanpa Luminatics, aku tak bisa...",
  ui_story_5009_50091002_49_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5009_50091002_50_dialog_content = "Hukum para pemberontak itu! Bantai para Eclipsite itu!",
  ui_story_5009_50091002_51_dialog_content = "Para pelarian dari keluarga Pyrrhus bersembunyi di sini! Buru mereka!",
  ui_story_5009_50091002_52_dialog_content = "Lari, Paloma!",
  ui_story_5009_50091002_53_dialog_content = "Tidak tanpamu!",
  ui_story_5009_50091002_54_dialog_content = "Kau harus tetap hidup, Paloma! Untuk membalaskan dendam kita... Kau harus bertahan hidup!",
  ui_story_5009_50091101_1_dialog_content = "Semuanya, jangan sampai lengah! Tetap waspada!",
  ui_story_5009_50091101_2_dialog_content = "Tapi, aku tak merasakan keberadaan Eclipsite lagi di dekat sini...",
  ui_story_5009_50091101_3_dialog_content = "Tak apa... Dia hanya mengingatkan semua orang untuk mewaspadaiku.",
  ui_story_5009_50091101_4_dialog_content = "Aku ini memang pelarian dari keluarga Pyrrhus yang dianggap pemberontak, dan aku juga anggota True Order yang dianggap menghujat. Dilihat dari mana pun, aku memang sangat berbahaya dan tak bisa dipercaya.",
  ui_story_5009_50091101_5_dialog_content = "Kalau kau punya niat buruk kepada kami, mestinya kau sudah membunuh kami dari tadi dengan kemampuan samaran dan ledakanmu.",
  ui_story_5009_50091101_6_dialog_content = "...Baiklah, cukup sudah. Kita harus mencari Mirren!",
  ui_story_5009_50091101_7_dialog_content = "Eclipse-nya belum memudar, jadi dia pasti masih ada di sekitar sini.",
  ui_story_5009_50091101_8_dialog_content = "Akan kucoba merasakan keberadaannya lagi.",
  ui_story_5009_50091101_9_dialog_content = "PlayerName, jangan terlalu memaksakan diri, ya?",
  ui_story_5009_50091101_10_dialog_content = "Aku akan baik-baik saja, Vice. Aku akan berusaha mengendalikan diri.",
  ui_story_5009_50091101_11_dialog_content = "Kalau kau bisa menemukannya, aku punya cara untuk menghabisinya.",
  ui_story_5009_50091101_12_option_content = "Rasakan",
  ui_story_5009_50091101_13_dialog_content = "Paloma! Lari!",
  ui_story_5009_50091101_A2_dialog_content = "Lari!!!",
  ui_story_5009_50091101_14_dialog_content = "Ayah? Ibu...!",
  ui_story_5009_50091101_A1_dialog_content = "Paloma... Ikutlah denganku! Cepat!",
  ui_story_5009_50091101_15_dialog_content = "Aduh...",
  ui_story_5009_50091101_16_dialog_content = "Menjauhlah darinya!",
  ui_story_5009_50091101_17_dialog_content = "Apakah kamu gila, wanita ?! Beraninya kau menggigitku!",
  ui_story_5009_50091101_18_dialog_content = "P... Paloma...",
  ui_story_5009_50091101_19_dialog_content = "Hah? Kenapa kau menatapku?",
  ui_story_5009_50091101_20_dialog_content = "Uh... Sepertinya emosi kuat yang kaurasakan memengaruhi kemampuan psikisku.",
  ui_story_5009_50091101_21_dialog_content = "Cih.",
  ui_story_5009_50091101_22_dialog_content = "Aku akan menjauh agar \"emosi kuat yang kurasakan\" ini tak mengganggumu.",
  ui_story_5009_50091101_23_dialog_content = "Emosi yang kuat...? Sepertinya kebencian Paloma kepada Mirren cukup kuat.",
  ui_story_5009_50091101_24_dialog_content = "Walaupun Paloma tak banyak bicara, sepertinya aku akhirnya paham.",
  ui_story_5009_50091101_25_dialog_content = "Kalau benar Mirren memang dalang di balik semua pemberontakan ini, memang masuk akal jadinya.",
  ui_story_5009_50091101_26_dialog_content = "Oh?",
  ui_story_5009_50091101_27_dialog_content = "Lady Carleen, keluarga Pyrrhus-lah yang menyebabkan terjadinya insiden yang menimpa Beryl.",
  ui_story_5009_50091101_28_dialog_content = "Atas alasan itu, keluarga Gautier yakin bahwa mereka diasingkan secara tak adil akibat perbuatan keluarga Pyrrhus.",
  ui_story_5009_50091101_29_dialog_content = "Untuk melancarkan aksi balas dendam, Mirren mengatur pemberontakan keluarga Gautier.",
  ui_story_5009_50091101_30_dialog_content = "Bagi Paloma dan kerabatnya, tak adil pula kalau kedua keluarga mereka juga dibantai akibat siasat Mirren itu.",
  ui_story_5009_50091101_31_dialog_content = "Karenanya, perseteruan di antara kedua keluarga ini sebenarnya sederhana saja.",
  ui_story_5009_50091101_32_dialog_content = "Dan Paloma tak bisa memaafkan Mirren, karena dialah yang menyebabkan kematian keluarganya.",
  ui_story_5009_50091101_33_dialog_content = "Sebentar... Bukannya ini semua karena penilaian pemerintah Lumopolis yang tak adil?",
  ui_story_5009_50091101_34_dialog_content = "...",
  ui_story_5009_50091101_35_dialog_content = "Masih ada banyak detail yang harus diklarifikasi. Tenanglah, Lady Carleen. Aku akan terus menyelidiki masalah ini semampuku.",
  ui_story_5009_50091101_36_dialog_content = "Satu hal yang masih belum bisa kupahami adalah kenapa Mirren dan Paloma sama-sama memiliki kekuatan sebesar itu.",
  ui_story_5009_50091101_37_dialog_content = "Aku di sini, lho. Lihat, 'kan?",
  ui_story_5009_50091101_38_dialog_content = "Memangnya aneh kalau aku jadi sangat kuat? Aku kan terperosok begitu dalam sampai-sampai bergabung dengan True Order.",
  ui_story_5009_50091101_39_dialog_content = "Soal Mirren, dari yang kutahu, kekuatannya ada hubungannya dengan organisasi misterius itu...",
  ui_story_5009_50091101_40_dialog_content = "Aku juga berpikir begitu, Nona Paloma.",
  ui_story_5009_50091101_41_dialog_content = "Bahkan kejadian tujuh belas tahun lalu itu, dan segala yang sudah terjadi hingga hari ini, semuanya mungkin saja berhubungan dengan...",
  ui_story_5009_50091101_42_dialog_content = "Jangan bicara penuh teka-teki begitu. Kalian berdua sedang membicarakan Eclipse, 'kan?",
  ui_story_5009_50091101_43_dialog_content = "Kita sudah pernah bertarung bersama mereka. Bisa dibilang, sekarang kita ini teman lama. Iya, 'kan, PlayerName?",
  ui_story_5009_50091101_44_dialog_content = "Tunggu...",
  ui_story_5009_50091101_45_dialog_content = "Aku bisa merasakan sesuatu! Mirren belum berhasil pergi dari Eraveil!",
  ui_story_5009_50091101_46_dialog_content = "Ada sebuah gua bawah tanah... Banyak High-Level Eclipsite tinggal dalam hibernasi di sana!",
  ui_story_5009_50091101_47_dialog_content = "Apa yang akan dilakukannya di sana?",
  ui_story_5009_50091101_48_dialog_content = "Bukannya itu sudah jelas? Makan Eclipsite dan mendapatkan kembali Darkflow.",
  ui_story_5009_50091101_49_dialog_content = "Jangan sampai itu terjadi...",
  ui_story_5009_50091101_50_dialog_content = "PlayerName! Berikan petunjuk arah!",
  ui_story_5009_50091101_51_dialog_content = "Di suatu tempat di sana.",
  ui_story_5009_50091101_52_dialog_content = "Kau bisa terus menggunakan kemampuan psikis sekuat itu dalam Eclipse... Aku terkesan.",
  ui_story_5009_50091101_53_dialog_content = "Mirren Gautier... Aku akan menemukanmu.",
  ui_story_5009_50091101_54_dialog_content = "Kau mau ke sana sendirian, Paloma?",
  ui_story_5009_50091101_55_dialog_content = "Kenapa tidak istirahat sebentar saja dulu? Kita bisa mengalahkannya bersama-sama kalau kekuatan kita sudah pulih!",
  ui_story_5009_50091101_56_dialog_content = "Oh? Aku baru saja memujimu, dan sekarang kaukira kau bisa memerintahku?",
  ui_story_5009_50091101_57_dialog_content = "Tunggu, Paloma!",
  ui_story_5009_50091101_58_dialog_content = "Dia pergi begitu saja...",
  ui_story_5009_50091101_59_dialog_content = "Dengan kekuatan seperti yang dimilikinya, dia lebih dari sekadar mampu untuk bertindak sendirian.",
  ui_story_5009_50091101_60_dialog_content = "Walau begitu, tadi kekuatannya terkuras cukup banyak. Kalau Mirren berhasil memulihkan Darkflow-nya...",
  ui_story_5009_50091101_61_dialog_content = "Kurasa dia tak akan punya peluang untuk menang.",
  ui_story_5009_50091101_62_dialog_content = "Kita harus bergegas menyusulnya.",
  ui_story_5009_50091101_63_dialog_content = "Lagi-lagi ada rintangan, ya...",
  ui_story_5009_50091101_64_dialog_content = "Ayo kita lakukan!",
  ui_story_5009_50091202_1_dialog_content = "Kaubilang dulu kau mengenal Paloma?",
  ui_story_5009_50091202_2_dialog_content = "Ya.. Waktu itu, dia hanyalah seorang gadis kecil pendiam, pemalu, dan tak berdaya.",
  ui_story_5009_50091202_3_dialog_content = "Pendiam, pemalu... dan tak berdaya?",
  ui_story_5009_50091202_4_dialog_content = "Apa yang kita bicarakan ini Paloma yang sama?",
  ui_story_5009_50091202_5_dialog_content = "Kami bertemu di Dawn Academy bertahun-tahun yang lalu.",
  ui_story_5009_50091202_6_dialog_content = "Saat itu, aku yakin kelak dia akan menjadi biarawati paling luar biasa, tapi kemudian...",
  ui_story_5009_50091202_7_dialog_content = "Aku melihat namanya tertulis dalam daftar pelarian.",
  ui_story_5009_50091202_8_dialog_content = "Menurut catatan, kejahatannya adalah terlibat dalam pemberontakan keluarga serta mengkhianati gereja...",
  ui_story_5009_50091202_9_dialog_content = "Keluarga Pyrrhus, bersama keluarga Gautier, mengatur sebuah aksi pemberontakan keras...",
  ui_story_5009_50091202_10_dialog_content = "Seandainya dia tak kabur, mungkinkah Paloma juga akan dieksekusi oleh Lumopolis?",
  ui_story_5009_50091202_11_dialog_content = "Seperti semua anggota keluarganya yang lain...?",
  ui_story_5009_50091202_12_dialog_content = "......",
  ui_story_5009_50091202_13_dialog_content = "Kurasa... sekarang aku bisa memahaminya.",
  ui_story_5009_50091202_14_dialog_content = "Menjadi orang terakhir yang selamat di antara keluarganya, dan mencari penjelasan atas ini semua...",
  ui_story_5009_50091202_15_dialog_content = "Aku bisa sepenuhnya memahami perasaannya.",
  ui_story_5009_50091202_16_dialog_content = "Kau baik-baik saja, PlayerName?",
  ui_story_5009_50091202_17_dialog_content = "Mencari kebenaran dan memburu pelaku yang sesungguhnya, dan membalaskan dendam demi keluarganya...",
  ui_story_5009_50091202_18_dialog_content = "Kau juga pasti merasa seperti itu ya, PlayerName?",
  ui_story_5009_50091202_19_dialog_content = "Tidak, hukumannya akan jauh lebih berat.",
  ui_story_5009_50091202_20_dialog_content = "Apa kalian belum sadar? Kalau tak ada orang yang bisa menghentikan mereka atau mengubah keadaan agar jadi lebih baik...",
  ui_story_5009_50091202_21_dialog_content = "Tragedi ini pasti akan terulang lagi dan lagi...",
  ui_story_5009_50091202_22_dialog_content = "Benar. Kita harus menyelidiki hal yang menimpa mereka di masa lalu dengan jelas dan mencari penyebab sesungguhnya dari perseteruan ini. Hanya dengan itulah kita bisa mencegahnya agar tak terulang lagi.",
  ui_story_5009_50091202_23_dialog_content = "Tapi, kalau masalahnya ternyata ada di kalangan bangsawan Lumopolis... Bagaimana kita bisa memperbaikinya?",
  ui_story_5009_50091202_24_dialog_content = "Kita bisa menjawab pertanyaan itu lain kali saja. Sekarang, prioritas utama kita adalah Mirren.",
  ui_story_5009_50091202_25_dialog_content = "Di dalam sini!",
  ui_story_5009_50091202_26_dialog_content = "Aku yakin... Mirren ada di dalam sini!",
  ui_story_5009_50091202_27_dialog_content = "Tunggu! Suara apa itu...?",
  ui_story_5009_50091202_28_dialog_content = "<color=#e8d9bb>Gemuruh...!</color>",
  ui_story_5009_50091202_29_dialog_content = "Semuanya, jaga pijakan kalian!",
  ui_story_5009_50091202_30_dialog_content = "Gempanya berhenti...",
  ui_story_5009_50091202_31_dialog_content = "Bagaimana mungkin struktur di bawah tanah ini dibangun dengan sedemikian baiknya sampai mampu bertahan dari guncangan sebesar itu?",
  ui_story_5009_50091202_32_dialog_content = "Kalau ini adalah gua yang terbentuk secara alami, aku khawatir kemungkinan besar kita terjebak di dalamnya.",
  ui_story_5009_50091202_33_dialog_content = "Suara berisik apa itu?",
  ui_story_5009_50091202_34_dialog_content = "Asalnya dari dalam bangunan itu!",
  ui_story_5009_50091202_35_dialog_content = "PlayerName... Mungkinkah itu...?",
  ui_story_5009_50091202_36_dialog_content = "Ya... Aku bisa merasakan aura Paloma. Kemungkinan besar...",
  ui_story_5009_50091202_37_dialog_content = "Paloma sudah menemukan Mirren.",
  ui_story_5009_50091301_A1_dialog_content = "Mmmmm... Kekuatan! Kekuatan yang lezat!",
  ui_story_5009_50091301_1_dialog_content = "<color=#e8d9bb>Gemuruh...!</color>",
  ui_story_5009_50091301_A2_dialog_content = "Hahaha! Tepat waktu.",
  ui_story_5009_50091301_2_dialog_content = "Mirren Gautier... Kau tak lebih dari sekadar cacing licik dan pengecut.",
  ui_story_5009_50091301_3_dialog_content = "Benar, 'kan? Tapi, berubah menjadi cacing pun kau tak akan sempat!",
  ui_story_5009_50091301_4_dialog_content = "Ah...!",
  ui_story_5009_50091301_5_dialog_content = "Anggap saja ini sebagai pujian, kau memang luar biasa—karena bisa bertahan sampai di sini.",
  ui_story_5009_50091301_6_dialog_content = "Tapi, teknik rahasia True Order tak lebih dari sekadar Luminatics kacangan.",
  ui_story_5009_50091301_7_dialog_content = "Sama sekali tak ada apa-apanya dibandingkan kekuatanku... Kekuatan luar biasa yang dikaruniakan kepadaku oleh Masterku.",
  ui_story_5009_50091301_8_dialog_content = "Ehem... Kekuatan yang kaubicarakan ini... Bisakah hanya dipulihkan dengan cara yang tidak menyenangkan?",
  ui_story_5009_50091301_9_dialog_content = "Apa seleramu juga jadi hilang setelah kau berubah menjadi monster?",
  ui_story_5009_50091301_10_dialog_content = "Aku tak bisa membayangkan bagaimana perutmu bisa tahan memakan sebegitu banyak Eclipsite busuk itu.",
  ui_story_5009_50091301_11_dialog_content = "Oh? Sepertinya kau belum sadar, ya. Yang paling lezat di dunia ini adalah... kekuatan!",
  ui_story_5009_50091301_12_dialog_content = "Mau coba mencicipi? Ah ya, sekarang aku bisa lihat...",
  ui_story_5009_50091301_13_dialog_content = "Kalau kau mau memakan Darkflow ini, penampilanmu akan jadi lebih cantik lagi...",
  ui_story_5009_50091301_14_dialog_content = "Kau benar-benar mengira semua orang sama sepertimu, ya?",
  ui_story_5009_50091301_15_dialog_content = "*Menghela napas* Aku hanya ingin memberimu kesempatan untuk membayangkan apa yang bisa kaucapai...",
  ui_story_5009_50091301_16_dialog_content = "Tapi, kurasa akan lebih mudah kalau kukumpulkan saja sisa-sisa mayatmu dan membuat spesimen darinya!",
  ui_story_5009_50091301_17_dialog_content = "Lihat, itu Mirren!",
  ui_story_5009_50091301_18_dialog_content = "Celaka... Paloma, awas!",
  ui_story_5009_50091301_19_option_content = "Force Boost",
  ui_story_5009_50091301_20_dialog_content = "Menghindar mundur!",
  ui_story_5009_50091301_21_dialog_content = "Syukurlah! Aku tak mengira Ploma akan bisa menghindari serangan terakhir itu!",
  ui_story_5009_50091301_22_dialog_content = "Tetap saja, sekarang dia kelihatan sangat kelelahan...",
  ui_story_5009_50091301_23_dialog_content = "*Batuk-batuk* PlayerName...",
  ui_story_5009_50091301_24_dialog_content = "Kau tidak pernah minta izin sebelum menggunakan kemampuan psikismu, ya?",
  ui_story_5009_50091301_25_option_content = "Tidak juga...",
  ui_story_5009_50091301_26_dialog_content = "Aku hanya menggunakan kekuatanku seperti itu dalam situasi darurat!",
  ui_story_5009_50091301_27_option_content = "Aku tak punya pilihan lain...",
  ui_story_5009_50091301_28_dialog_content = "Aku tak boleh berpikir panjang dalam kondisi darurat...",
  ui_story_5009_50091301_29_dialog_content = "Oh? Kalau begitu, harusnya aku merasa beruntung.",
  ui_story_5009_50091301_30_dialog_content = "Kenapa lama sekali? Kalian melewatkan pertunjukan bagus, tahu!",
  ui_story_5009_50091301_31_dialog_content = "Tapi, kurasa tak masalah, sih. Karena...",
  ui_story_5009_50091301_32_dialog_content = "Pertunjukan yang sesungguhnya baru akan dimulai!",
  ui_story_5009_50091301_33_dialog_content = "Semuanya, awas!",
  ui_story_5009_50091301_34_dialog_content = "Jangan tempat aneh ini lagi, dong...",
  ui_story_5009_50091301_35_dialog_content = "Apa kita terlambat? Sepertinya kekuatannya sudah pulih. Aku tak bisa membayangkan berapa banyak Eclipsite yang dimangsanya sampai dia bisa pulih secepat itu...",
  ui_story_5009_50091301_36_dialog_content = "Minggir.",
  ui_story_5009_50091301_37_dialog_content = "<color=#e8d9bb>Brak! Brak! Brak!</color>",
  ui_story_5009_50091301_38_dialog_content = "Aku tak bisa menghancurkannya! Apa kekuatanku sudah terkuras terlalu banyak...?",
  ui_story_5009_50091301_39_option_content = "Coba rasakan",
  ui_story_5009_50091301_40_dialog_content = "Biar kucoba lagi...",
  ui_story_5009_50091301_41_option_content = "Force Boost!",
  ui_story_5009_50091301_42_dialog_content = "PlayerName...",
  ui_story_5009_50091301_43_dialog_content = "Kemampuan psikismu tak akan terlalu berguna di dalam ruang ciptaan si begundal itu.",
  ui_story_5009_50091301_44_dialog_content = "Sebentar, biar kupikirkan dulu... Pasti ada sesuatu yang bisa kita lakukan.",
  ui_story_5009_50091301_45_dialog_content = "Semuanya, waspadai serangan musuh!",
  ui_story_5009_50091301_46_dialog_content = "Shh! Diam...",
  ui_story_5009_50091301_47_dialog_content = "<color=#e8d9bb>Wuuss!</color>",
  ui_story_5009_50091301_48_dialog_content = "PlayerName! Cari jalan keluar dari sini; aku akan membendung serangan Mirren!",
  ui_story_5009_50091301_49_dialog_content = "Ba-baik!",
  ui_story_5009_50091301_50_dialog_content = "Hahaha! Oh, Paloma... Aku tak pernah menyangka kau tetap saja bersikap naif setelah semua yang terjadi ini.",
  ui_story_5009_50091301_51_dialog_content = "Coba saja bendung seranganku!",
  ui_story_5009_50091301_52_dialog_content = "Aduh...",
  ui_story_5009_50091301_53_dialog_content = "Kita tak bisa terus-terusan begini...",
  ui_story_5009_50091301_54_dialog_content = "Mirren! Aku satu-satunya wakil Lumopolis di sini, bukan mereka! Kalau kau mau meluapkan amarahmu kepada seseorang, luapkan saja kepadaku! Biarkan mereka pergi!",
  ui_story_5009_50091301_55_dialog_content = "Oh? Sepertinya barusan kudengar hal menarik.",
  ui_story_5009_50091301_56_dialog_content = "Apa katamu barusan? \"Biarkan mereka pergi\"? Hahahahaha! Jangan membuatku tertawa!",
  ui_story_5009_50091301_57_dialog_content = "Apa hanya nyawa teman-temanmu saja yang pantas dikasihani? Mana belas kasihan itu saat keluargaku dibantai bertahun-tahun lalu?!",
  ui_story_5009_50091301_58_dialog_content = "Ini pasti berarti nyawa keluarga Nona Paloma juga tak layak menerima belas kasihanmu. Benar, 'kan?!",
  ui_story_5009_50091301_59_dialog_content = "Mirren Gautier... Keluargamu memang tak bersalah, tapi kau jelas-jelas salah.",
  ui_story_5009_50091301_60_dialog_content = "Kau memilih untuk menyulut kekerasan, dan seluruh keluargamu terpaksa menderita dan mati karenanya.",
  ui_story_5009_50091301_61_dialog_content = "Kata-katamu hanya buang-buang waktu saja.",
  ui_story_5009_50091301_62_dialog_content = "Omong kosong... Kata-katamulah yang tak ada artinya, bukan kata-kataku!",
  ui_story_5009_50091301_63_dialog_content = "Tak ada bedanya dengan makhluk egois... Matilah sekarang!",
  ui_story_5009_50091301_64_dialog_content = "Hahaha! Lagi-lagi kau menutup mata dari kebenaran? Kalau bukan karena sikap masa bodohmu itu, keluarga kami tak akan diasingkan.",
  ui_story_5009_50091301_65_dialog_content = "Dulu, aku memang tak punya kekuatan, dan aku dianiaya karenanya.",
  ui_story_5009_50091301_66_dialog_content = "Tapi, setelah punya kekuatan, orang-orang takut dan patuh kepadaku... Mereka bahkan memujaku...",
  ui_story_5009_50091301_67_dialog_content = "Sayangnya, keluargaku tak bisa memahami dan menerimanya, dan karenanya terpaksa dibereskan oleh Lumopolis.",
  ui_story_5009_50091301_68_dialog_content = "Aku sendiri senang melihat wajah-wajah kalian yang sok suci tapi penuh ketakutan itu saat kalian berdiri tanpa daya menghadapi kekuatanku.",
  ui_story_5009_50091301_69_dialog_content = "Inilah keadilan MENURUTKU.",
  ui_story_5009_50091301_70_dialog_content = "Lagi-lagi monolog muluk-muluk tentang kekuatan... Aku sudah muak dengan omongan sampah ini.",
  ui_story_5009_50091301_71_dialog_content = "Kau tak pantas bicara tentang keadilan setelah kautukar jiwamu dengan kekuatan.",
  ui_story_5009_50091301_72_dialog_content = "Dan jangan bicara tentang keluargamu seakan-akan mereka tak lebih dari sekadar alat bagimu.",
  ui_story_5009_50091301_73_dialog_content = "Mirren... apa kau memang selalu dramatis, ataukah itu akibat dari transformasimu?",
  ui_story_5009_50091301_74_dialog_content = "Hah!",
  ui_story_5009_50091301_78_dialog_content = "Hmph, kesabaranku sudah habis.",
  ui_story_5009_50091301_79_dialog_content = "Sudah waktunya mengirim kalian semua ke neraka, bersama seluruh kaum Caelestite!",
  ui_story_5009_50091301_75_dialog_content = "Minggir, PlayerName!",
  ui_story_5009_50091301_A3_dialog_content = "Langkahi dulu mayatku!",
  ui_story_5009_50091301_80_dialog_content = "Paloma... Kamu masih bisa bertarung?",
  ui_story_5009_50091301_82_dialog_content = "Apa?!",
  ui_story_5009_50091301_A4_dialog_content = "Jangan berdiri saja di sana—cobalah jangan sampai tertinggal. Ayo kita serang bersama... Jangan berhenti sampai ini berakhir!",
  ui_story_5009_50091301_A5_dialog_content = "Jadi, rupanya kau tahu apa itu kerja sama tim! Prajurit, ikuti aku!",
  ui_story_5009_50091301_A6_dialog_content = "Aku tak punya pilihan lain... Ice Blossom!",
  ui_story_5009_50091301_A7_dialog_content = "Terimalah hukumanmu!",
  ui_story_5009_50091301_A8_dialog_content = "Benar sekali, teman-teman... Kita tak boleh membiarkannya begitu saja!",
  ui_story_5009_50091301_76_dialog_content = "Cih!",
  ui_story_5009_50091301_77_option_content = "Tautkan pikiran!",
  ui_story_5009_50091301_A9_dialog_content = "Aduh... Kepalaku...",
  ui_story_5009_50091301_A10_dialog_content = "Tapi, ini Eraveil... Bukan...",
  ui_story_5009_50091301_A11_dialog_content = "Sungguh? Sepertinya kendaliku atas Luminatics sedikit meningkat!",
  ui_story_5009_50091301_A12_dialog_content = "Sama.",
  ui_story_5009_50091301_A13_dialog_content = "Serangan kita semua berhasil... Kita lolos dari kendali tempat ini!",
  ui_story_5009_50091301_81_dialog_content = "Kemampuan psikisku juga sudah sedikit pulih!",
  ui_story_5009_50091301_83_dialog_content = "Mirren Gautier... Tak peduli apa yang telah kaulakukan atau penderitaan apa yang sudah kausebabkan di masa lalu...",
  ui_story_5009_50091301_84_dialog_content = "Kau membawa kehancuran ke Eraveil dalam nama Eclipse!",
  ui_story_5009_50091301_85_dialog_content = "Aku tak akan mengampunimu karena itu!",
  ui_story_5009_50091301_86_dialog_content = "Hahahaha! Sungguh kata-kata hebat dari makhluk ringkih sepertimu!",
  ui_story_5009_50091301_87_dialog_content = "Baiklah! Kalau memang harus begini jadinya... aku akan mengerahkan segenap kekuatanku untuk melumatmu!",
  ui_story_5009_50091301_88_dialog_content = "Graaaaaagh!!!",
  ui_story_5009_50091301_89_dialog_content = "Kalian semua sudah siap? Sudah waktunya mengakhiri ini!",
  ui_story_5009_50091301_90_dialog_content = "Kemampuan psikismu... sudah pulih?",
  ui_story_5009_50091301_91_dialog_content = "Hmph, aku selalu siap. Ayo!",
  ui_story_5009_50091301_92_option_content = "Aktifkan kekuatan!",
  ui_story_5009_50091302_1_dialog_content = "Cahayanya terang sekali...",
  ui_story_5009_50091302_2_dialog_content = "Eclipse-nya berangsur sirna.",
  ui_story_5009_50091302_3_dialog_content = "Lagi-lagi dia berhasil kabur...",
  ui_story_5009_50091302_4_dialog_content = "Mirren Gautier... selalu bersikap licik.",
  ui_story_5009_50091302_5_dialog_content = "Begitu situasi mulai berbalik, dia memanfaatkan kecerdikannya untuk kabur.",
  ui_story_5009_50091302_6_dialog_content = "Tapi, kali ini kita benar-benar berhasil mencederainya. Kurasa kita tak akan melihatnya lagi dalam waktu lama.",
  ui_story_5009_50091302_7_dialog_content = "Mirren Gautier... Apa dia datang ke Eraveil tujuh belas tahun lalu?",
  ui_story_5009_50091302_8_dialog_content = "Kenapa kau menanyakannya?",
  ui_story_5009_50091302_9_dialog_content = "Tujuh belas tahun lalu, saat Eraveil dan Caelestite dimusnahkan... Saat itu, ada Eclipse di langit, persis seperti hari ini.",
  ui_story_5009_50091302_10_dialog_content = "Kupikir mungkin ada...",
  ui_story_5009_50091302_11_dialog_content = "Maaf, tapi aku tak tahu...",
  ui_story_5009_50091302_12_dialog_content = "Sebelum keluarga kami diasingkan dan diusir ke Lower Lumopolis, menurutku Mirren tidak benar-benar pergi dari Lumopolis.",
  ui_story_5009_50091302_13_dialog_content = "Kapan tepatnya keluargamu diasingkan?",
  ui_story_5009_50091302_14_dialog_content = "Dua belas tahun lalu.",
  ui_story_5009_50091302_15_dialog_content = "Jadi... Mungkin bukan dia penyebabnya, ya?",
  ui_story_5009_50091302_16_dialog_content = "Dari informasi yang berhasil kami kumpulkan, kurasa...",
  ui_story_5009_50091302_17_dialog_content = "Orang yang disebut \"Master\" oleh Mirren itulah yang lebih mungkin punya keterlibatan dalam hal ini.",
  ui_story_5009_50091302_18_dialog_content = "...!",
  ui_story_5009_50091302_19_dialog_content = "Seberapa banyak yang kauketahui tentang Eclipse, Paloma?",
  ui_story_5009_50091302_20_dialog_content = "Aku juga ingin menanyakan hal itu!",
  ui_story_5009_50091302_21_dialog_content = "Kemunculan Eclipse... mungkin adalah kekuatan yang dimiliki organisasi mereka.",
  ui_story_5009_50091302_22_dialog_content = "Di area yang terkena pengaruh Eclipse, Luminatics milik orang-orang melemah.",
  ui_story_5009_50091302_23_dialog_content = "Kemampuan psikisku juga terpengaruh sejak awal...",
  ui_story_5009_50091302_24_dialog_content = "Bagaimana dengan ruang aneh barusan? Apa itu?",
  ui_story_5009_50091302_25_dialog_content = "Ruang itu semacam zona Eclipse yang terselubung dan terpusat, dan efek pelemahannya jauh lebih besar.",
  ui_story_5009_50091302_26_dialog_content = "Sulit sekali menembus keluar dari dalam ruang itu, tapi lebih mudah menghancurkannya dari luar.",
  ui_story_5009_50091302_27_dialog_content = "Soal \"Master\"-nya...",
  ui_story_5009_50091302_28_dialog_content = "Kaumku... Apakah kaum Caelestite dihancurkan oleh serangan seperti itu?",
  ui_story_5009_50091302_29_dialog_content = "Bagaimana kau bisa tahu begitu banyak tentang Mirren Gautier, Pluma? Atau tentang cara kerja Eclipse?",
  ui_story_5009_50091302_30_dialog_content = "Oh? Sekarang kau malah mencurigaiku, ya?",
  ui_story_5009_50091302_31_dialog_content = "Ma-maafkan aku.",
  ui_story_5009_50091302_32_dialog_content = "Aku hanya penasaran. Kenapa kekuatanmu tak terpengaruh oleh Eclipse?",
  ui_story_5009_50091302_33_dialog_content = "Kalau sudah dikuasai keinginan untuk membalas dendam, hal-hal lain tak akan terlalu berpengaruh.",
  ui_story_5009_50091302_34_dialog_content = "Ini hanyalah konsekuensi yang harus kutanggung. Kurasa kau tak akan pernah bisa memahaminya.",
  ui_story_5009_50091302_35_dialog_content = "Apa kau juga berniat membalas dendam kepada Lumopolis?",
  ui_story_5009_50091302_36_dialog_content = "Oh? Sepertinya kau lebih cermat daripada yang kuduga, Putri Lumopolis...",
  ui_story_5009_50091302_37_dialog_content = "Tenanglah. Ini bukan waktunya untuk Lumopolis... belum.",
  ui_story_5009_50091302_38_dialog_content = "Kalau begitu, kau harus tahu bahwa aku tak akan membiarkanmu membahayakan Lumopolis atau rakyatnya.",
  ui_story_5009_50091302_39_dialog_content = "Hmm... Kita tunggu dan lihat saja nanti, ya?",
  ui_story_5009_50091302_40_dialog_content = "Balas dendam, ya?",
  ui_story_5009_50091302_41_dialog_content = "Aku tak tahu bagaimana dengan yang lainnya... tapi aku yakin kau sangat paham perasaanku ini. Iya, 'kan, PlayerName?",
  ui_story_5009_50091302_42_dialog_content = "...Kau mau menjadi Eclipsite hanya agar bisa membalaskan dendammu?",
  ui_story_5009_50091302_43_dialog_content = "Leluconmu sedikit terlalu timpang untuk seleraku, PlayerName.",
  ui_story_5009_50091302_44_dialog_content = "Aku ingin menanyakan hal yang sama: apa KAU mau menjadi Eclipsite hanya demi membalaskan dendammu?",
  ui_story_5009_50091302_45_dialog_content = "Tentu saja aku tak mau!",
  ui_story_5009_50091302_46_dialog_content = "Kalau begitu, kita sama!",
  ui_story_5009_50091302_47_dialog_content = "Hahaha... Kurasa kita punya banyak kesamaan, PlayerName. Tapi...",
  ui_story_5009_50091302_48_dialog_content = "Aku juga merasa bahwa mengobrol seperti ini hanya buang-buang waktu saja. Aku harus pergi sekarang.",
  ui_story_5009_50091302_49_dialog_content = "Paloma.",
  ui_story_5009_50091302_50_dialog_content = "Kau dan Beryl...",
  ui_story_5009_50091302_51_dialog_content = "Ah... Aku tahu apa yang mau kautanyakan, PlayerName.",
  ui_story_5009_50091302_52_dialog_content = "Balas dendamku tak ada hubungannya dengan Beryl.",
  ui_story_5009_50091302_53_dialog_content = "Kalau begitu, apa dia... baik-baik saja?",
  ui_story_5009_50091302_54_dialog_content = "Hmph, bukannya kalian berdua bekerja sama membangun Kantor Pos?",
  ui_story_5009_50091302_55_dialog_content = "Kalau memang ingin tahu, tulis saja surat dan tanyakan langsung kepadanya.",
  ui_story_5009_50091302_56_dialog_content = "Aku harus pergi sekarang.",
  ui_story_5009_50091302_57_dialog_content = "Tunggu, Nona Paloma.",
  ui_story_5009_50091302_58_dialog_content = "Apa? Kau mau menangkapku sebelum aku kabur?",
  ui_story_5009_50091302_59_dialog_content = "Aku ingin membuka kembali penyelidikan tentang keluarga Pyrrhus dan Gautier dan meneliti masalah ini lebih lanjut.",
  ui_story_5009_50091302_60_dialog_content = "Tentu saja, itu kalau kau mau kembali bersamaku ke Hall of Justice...",
  ui_story_5009_50091302_61_dialog_content = "Lalu apa? Memberimu kesempatan untuk memenuhi tugasmu dengan menangkapku?",
  ui_story_5009_50091302_62_dialog_content = "Kumohon, Paloma! Kau tahu aku bukan orang seperti itu!",
  ui_story_5009_50091302_63_dialog_content = "Aku hanya ingin tahu kebenarannya agar kami bisa meluruskan perkara ini.",
  ui_story_5009_50091302_64_dialog_content = "Begitukah? Kalau begitu, aku ingin bertanya: apa kau tahu kenapa kalangan elite Lumopolis memilih untuk menyembunyikan kebenarannya?",
  ui_story_5009_50091302_65_dialog_content = "Apa kau tahu siapa dalang di balik semua ini?",
  ui_story_5009_50091302_66_dialog_content = "Tidak, kau tak tahu.",
  ui_story_5009_50091302_67_dialog_content = "Benar. Aku tak tahu, dan aku tak perlu tahu.",
  ui_story_5009_50091302_68_dialog_content = "Aku hanya perlu tahu bahwa tugasku adalah menyelidiki kebenarannya.",
  ui_story_5009_50091302_69_dialog_content = "...Hah?",
  ui_story_5009_50091302_70_dialog_content = "Dulu, aku dan beberapa rekanku ditugaskan ke Umbraton untuk menyelidiki hal ini, tapi kami malah bertemu dengan anggota Eclipse...",
  ui_story_5009_50091302_71_dialog_content = "*Batuk-batuk* Kau baik-baik saja...?",
  ui_story_5009_50091302_72_dialog_content = "Pittman... Kakiku sudah tak sanggup lagi...",
  ui_story_5009_50091302_73_dialog_content = "Tapi kau... dan yang lainnya...",
  ui_story_5009_50091302_74_dialog_content = "Kalau kau terus-terusan buang-buang waktu, kita semua akan binasa!",
  ui_story_5009_50091302_75_dialog_content = "Sana, pergilah!",
  ui_story_5009_50091302_76_dialog_content = "Orang tua dan anak-anak mereka, suami dan istri mereka...",
  ui_story_5009_50091302_77_dialog_content = "Sebagai satu-satunya orang yang selamat dari serangan itu, aku harus menjelaskan kematian orang-orang terkasih mereka.",
  ui_story_5009_50091302_78_dialog_content = "Kurasa sekarang aku bisa lebih memahami perasaanmu... Tapi, Yang Mulia, hentikan pikiranmu yang sok suci itu!",
  ui_story_5009_50091302_79_dialog_content = "Dengan kekuatanmu, kau tak akan pernah bisa menemukan kebenarannya.",
  ui_story_5009_50091302_80_dialog_content = "God of Light telah memercayakan tugas ini kepadaku. Aku tak boleh dan tak akan gagal menjalankannya.",
  ui_story_5009_50091302_81_dialog_content = "Keadilan mungkin butuh waktu lama untuk ditegakkan, tapi suatu hari nanti pasti akan terwujud!",
  ui_story_5009_50091302_82_dialog_content = "......",
  ui_story_5009_50091302_83_dialog_content = "*Menghela napas* Kalau begitu, aku hanya bisa...",
  ui_story_5009_50091302_84_dialog_content = "Berharap semoga kalian berhasil.",
  ui_story_5009_50091302_85_dialog_content = "Sampai jumpa lagi, PlayerName!",
  ui_story_5009_50091302_86_dialog_content = "Paloma! Tunggu!",
  ui_story_5009_50091302_87_dialog_content = "......",
  ui_story_5009_50091302_88_dialog_content = "Benarkah tak apa... kalau kita begitu saja melepaskan seorang pelarian?",
  ui_story_5009_50091302_89_dialog_content = "Jangan ikut campur.",
  ui_story_5009_50091302_90_dialog_content = "Apa yang akan kaukatakan kepada atasanmu, Pittman?",
  ui_story_5009_50091302_91_dialog_content = "Apa adanya, Lady Carleen. Aku akan melaporkan kebenaran tak terbantahkan ini kepada mereka.",
  ui_story_5009_50091302_92_dialog_content = "Tapi, apa kau tak khawatir Hall of Justice akan menyalahkanmu karena membiarkan seorang pelarian pergi begitu saja?",
  ui_story_5009_50091302_93_dialog_content = "Sepertinya ada sejumlah kasus dalam satu dekade terakhir ini yang lebih rumit dari kelihatannya dan harus diselidiki lebih lanjut.",
  ui_story_5009_50091302_94_dialog_content = "Aku yakin bahwa Hall of Justice, serta Chief Judge, tak akan mengabaikan kenyataan bahwa kasus-kasus ini perlu diklarifikasi. Mereka juga tak akan menghukumku tanpa alasan jelas.",
  ui_story_5009_50091302_95_dialog_content = "Dalam nama God of Light, aku bersumpah akan mencari kebenarannya, apa pun konsekuensi yang harus kutanggung.",
  ui_story_5009_50091302_96_dialog_content = "Lumopolis sangat beruntung punya hakim sepertimu. Aku percaya kepadamu.",
  ui_story_5009_50091302_97_dialog_content = "Aku... aku juga percaya kepadamu, Pittman!",
  ui_story_5009_50091302_98_dialog_content = "*Berdehem* Hei, PlayerName!",
  ui_story_5009_50091302_99_dialog_content = "Apa kau masih ingat apa sebenarnya tujuan kita kemari?",
  ui_story_5009_50091302_100_option_content = "Aku ingat...",
  ui_story_5009_50091302_101_dialog_content = "Kita kemari untuk melihat Eraveil.",
  ui_story_5009_50091302_102_option_content = "Aku benar-benar lupa...",
  ui_story_5009_50091302_103_dialog_content = "*Menghela napas* Bukannya kita kemari untuk membantu membangun ulang Kantor Pos?",
  ui_story_5009_50091302_104_dialog_content = "Aku penasaran, apakah Naroxel dan yang lainnya juga terpengaruh oleh Eclipse tadi itu?",
  ui_story_5009_50091302_105_dialog_content = "Aku sih tak akan terlalu khawatir soal itu.",
  ui_story_5009_50091302_106_dialog_content = "Sistem komunikasi sudah kembali berfungsi, dan melihat dari pesan yang dikirimkannya lewat terminal...",
  ui_story_5009_50091302_107_dialog_content = "Sepertinya mereka sedang sangat sibuk.",
  ui_story_5009_50091302_108_dialog_content = "Kalau begitu, kita tak boleh bersantai-santai dulu.",
  ui_story_5009_50091302_109_dialog_content = "Apa ada Eclipsite yang masih bersembunyi di Eraveil, PlayerName?",
  ui_story_5009_50091302_110_dialog_content = "Ya... Aku bisa merasakan masih ada beberapa Eclipsite level rendah yang bersembunyi di sekitar sini.",
  ui_story_5009_50091302_111_dialog_content = "Kalau begitu, kita harus segera bergerak dan membereskan mereka.",
  ui_story_5009_50091302_112_dialog_content = "Semuanya, ayo kita habisi mereka sebelum matahari terbenam!",
  ui_story_5009_50091302_113_dialog_content = "Ayo!",
  ui_story_5009_50091302_114_dialog_content = "A-anu...",
  ui_story_5009_50091302_115_dialog_content = "Kalian menuju arah yang salah... Para Eclipsite ada di arah sana!",
  ui_story_5009_50091401_1_dialog_content = "Sepertinya sebentar lagi malam tiba.",
  ui_story_5009_50091401_2_dialog_content = "Bagaimana status situasinya, PlayerName?",
  ui_story_5009_50091401_3_dialog_content = "Eraveil...",
  ui_story_5009_50091401_4_dialog_content = "Rupanya masih ada yang tersisa, ya? Sial... Tak mungkin kita bisa menghabisi mereka semua!",
  ui_story_5009_50091401_5_dialog_content = "Mana yang lainnya? Mereka tak akan bisa sembunyi dariku!",
  ui_story_5009_50091401_6_dialog_content = "Aku tak merasakan keberadaan Eclipsite lagi di Eraveil!",
  ui_story_5009_50091401_7_dialog_content = "Sudah kubilang, 'kan! Aku tahu kau pasti bisa menghabisi mereka semua sebelum matahari terbenam!",
  ui_story_5009_50091401_8_dialog_content = "Kerja bagus, semuanya. Tak ada yang mustahil, asalkan kita tak menyerah.",
  ui_story_5009_50091401_9_dialog_content = "Apa semua Eclipsite itu sudah mati?",
  ui_story_5009_50091401_10_dialog_content = "Tunggu... Kita menang?",
  ui_story_5009_50091401_11_dialog_content = "Ya, kita menang... Dan ini semua berkat bantuan dari semua orang.",
  ui_story_5009_50091401_12_dialog_content = "Ya! Kita menang!!!",
  ui_story_5009_50091401_13_dialog_content = "<color=#e8d9bb>Nguung, nguung, ngung...</color>",
  ui_story_5009_50091401_14_dialog_content = "Hmm? Tunggu... Suara apa itu?",
  ui_story_5009_50091401_15_dialog_content = "Oh, itu hanya suara notifikasi dari terminalku.",
  ui_story_5009_50091401_16_dialog_content = "Ma-maaf, biar kulihat sebentar...",
  ui_story_5009_50091401_17_dialog_content = "Hai, Vice.",
  ui_story_5009_50091401_18_dialog_content = "Ternyata Naroxel!",
  ui_story_5009_50091401_19_dialog_content = "Halo, Naroxel! Bagaimana keadaanmu?",
  ui_story_5009_50091401_20_dialog_content = "Oh? Sepertinya PlayerName juga bersamamu.",
  ui_story_5009_50091401_21_dialog_content = "Bagaimana situasi di Eraveil? Apa areanya masih dipenuhi aktivitas Eclipsite?",
  ui_story_5009_50091401_22_dialog_content = "Oh, tak usah khawatir! Berkat bantuan dari semua orang, kami berhasil menumpas para Eclipsite di Eraveil!",
  ui_story_5009_50091401_23_dialog_content = "Terima kasih kepada restu dari alam! Tadi aku sempat khawatir tentang keadaan kalian...",
  ui_story_5009_50091401_24_dialog_content = "Tapi, mendengar suaramu yang ceria dan bersemangat, aku jadi tenang.",
  ui_story_5009_50091401_25_dialog_content = "Sebenarnya hari ini... terasa cukup melelahkan. Bagaimana keadaan kalian di sana? Apa ada masalah besar?",
  ui_story_5009_50091401_26_dialog_content = "Semuanya berjalan lancar... Tapi, penyakit Dove tetap jadi hal yang perlu dikhawatirkan.",
  ui_story_5009_50091401_27_dialog_content = "Tunggu... Dove benar-benar datang ke sana?",
  ui_story_5009_50091401_28_dialog_content = "Ya, tapi dia sakit berat, dan jelas dia butuh istirahat. Aku sudah memanggil kendaraan pengangkut untuk membawanya sesegera mungkin.",
  ui_story_5009_50091401_29_dialog_content = "*Menghela napas* Aku penasaran, jangan-jangan si merpati kecil itu hanya pura-pura agar tak perlu bekerja...",
  ui_story_5009_50091401_30_dialog_content = "Kurasa dia tak pura-pura, karena sepertinya dia sakit karena terlalu lelah bekerja.",
  ui_story_5009_50091401_31_dialog_content = "Aku sama sekali tak menyangka Dove bisa bekerja keras sampai kelelahan...",
  ui_story_5009_50091401_32_dialog_content = "Hari ini, dia benar-benar banyak membantu. Kalau kaulihat sendiri, kau akan paham.",
  ui_story_5009_50091401_33_dialog_content = "Hah? Ba-baiklah kalau begitu.",
  ui_story_5009_50091401_34_dialog_content = "Oh, dan Tweety memintaku memberitahumu, ada kejutan besar menantimu di Kantor Pos.",
  ui_story_5009_50091401_35_dialog_content = "Tapi... Kalau kuberi tahu tentang ini, bukannya jadinya bukan kejutan lagi, ya?",
  ui_story_5009_50091401_36_dialog_content = "Sudahlah, kalian pasti kelelahan setelah menjalani hari yang berat ini.",
  ui_story_5009_50091401_37_dialog_content = "Kami sudah menyiapkan teh panas dan camilan di Kantor Pos untuk menyambut kedatangan kalian.",
  ui_story_5009_50091401_38_dialog_content = "Paham! Kami akan segera ke sana. Sampai jumpa!",
  ui_story_5009_50091401_39_dialog_content = "Aku penasaran, apa ya yang dimaksud \"kejutan besar\" itu?",
  ui_story_5009_50091401_40_dialog_content = "Aku tak yakin, tapi dia memang suka berbuat hal-hal tak terduga. Jujur saja, sebenarnya aku tak sabar ingin mengetahuinya!",
  ui_story_5009_50091401_41_dialog_content = "Kuharap kejutannya bagus, bukan kejutan yang membuat pusing.",
  ui_story_5009_50091401_42_dialog_content = "Nah, karena sekarang Eraveil sudah aman dari ancaman Eclipsite...",
  ui_story_5009_50091401_43_dialog_content = "Yang mulia, PlayerName, Wakil... Saya yakin ini saatnya saya kembali ke Lumopolis untuk membuat laporan.",
  ui_story_5009_50091401_44_dialog_content = "Apa? Kau mau pergi sekarang?",
  ui_story_5009_50091401_45_dialog_content = "Ayolah, Pittman. Aku yakin Hall of Justice akan paham kalau kau tinggal di sini sebentar lagi.",
  ui_story_5009_50091401_46_dialog_content = "Tak perlu buru-buru.",
  ui_story_5009_50091401_47_dialog_content = "Benar! Apalagi, lukamu akibat pertarungan hari ini pun belum diobati...",
  ui_story_5009_50091401_48_dialog_content = "Bagaimana kalau kau tinggal bersama kami dan istirahat sebentar? Aku merasa terhormat menerimamu sebagai tamuku!",
  ui_story_5009_50091401_49_dialog_content = "Terima kasih atas kebaikan kalian semua, tapi sayangnya aku terpaksa menolaknya.",
  ui_story_5009_50091401_50_dialog_content = "Setelah menghadapi masalah ini bersama kalian, ada banyak hal yang perlu kupertimbangkan... Tekadku pun jadi makin kuat karenanya.",
  ui_story_5009_50091401_51_dialog_content = "Berkat bantuan kalian semua, aku jadi tahu banyak dan bisa mendapatkan banyak petunjuk penyelidikan di Eraveil.",
  ui_story_5009_50091401_52_dialog_content = "Karena itu, aku ingin segera menyusun laporanku dan melanjutkan penyelidikanku.",
  ui_story_5009_50091401_53_dialog_content = "Kalau memang begitulah keinginanmu, kami paham...",
  ui_story_5009_50091401_54_dialog_content = "Tapi, kalau punya waktu luang, jangan lupa mengunjungi kami lagi, ya?",
  ui_story_5009_50091401_55_dialog_content = "Tentu saja, PlayerName. Aku punya firasat...",
  ui_story_5009_50091401_56_dialog_content = "Bahwa kita akan segera berjumpa lagi.",
  ui_story_5009_50091401_57_dialog_content = "Kok bisa sih orang-orang ini datang dan pergi semau mereka?",
  ui_story_5009_50091401_58_dialog_content = "Kurasa semestinya kita tidak di sini, tapi melihat drama ini terungkap ternyata lumayan menghibur, ya?",
  ui_story_5009_50091401_59_dialog_content = "Ehem! Apa ada yang ingin kausampaikan kepada kami, prajurit?",
  ui_story_5009_50091401_60_dialog_content = "Ti-tidak, Officer!",
  ui_story_5009_50091401_61_dialog_content = "Ka-kami hanya membahas cara terbaik untuk pulang!",
  ui_story_5009_50091401_62_dialog_content = "Kalau tak ada yang keberatan, aku bisa mengantar kalian semua pulang dengan Colossus milikku. Bagaimana?",
  ui_story_5009_50091401_63_dialog_content = "Tapi, aku punya satu syarat.",
  ui_story_5009_50091401_64_dialog_content = "Syarat? Mereka kemari untuk membantu! Bukankah berlebihan kalau mengajukan syarat?",
  ui_story_5009_50091401_65_dialog_content = "Dengarkan dulu, Vice!",
  ui_story_5009_50091401_66_dialog_content = "Apa syaratmu? Kami akan mendengarkannya.",
  ui_story_5009_50091401_67_dialog_content = "Kalian semua akan menjadi tamu pertama yang kubawa pulang ke Eraveil, kampung halamanku...",
  ui_story_5009_50091401_68_dialog_content = "Tapi, setelah segala yang kita lalui hari ini, dan semua bantuan yang kalian berikan, aku merasa selama ini aku belum menjadi tuan rumah yang baik bagi kalian...",
  ui_story_5009_50091401_69_dialog_content = "Jadi, aku ingin meminta kalian semua... Maukah kalian memberiku kesempatan lagi untuk menjamu kalian sebagai tamuku dan menjadi tuan rumah yang baik bagi kalian?",
  ui_story_5009_50091401_70_dialog_content = "Cuma itu? Hahaha! Aku sama sekali tak keberatan! Bagaimana dengan kalian?",
  ui_story_5009_50091401_71_dialog_content = "Menurutku, bagus juga! Akhirnya bisa istirahat! Baiklah!",
  ui_story_5009_50091401_72_dialog_content = "Maafkan aku, PlayerName, aku... Sepertinya aku salah menarik kesimpulan.",
  ui_story_5009_50091401_73_dialog_content = "Tapi, sebenarnya apa rencanamu untuk menjamu semua orang ini?",
  ui_story_5009_50091401_74_dialog_content = "Yah, sebenarnya... Beberapa hari lalu, aku memutuskan untuk bersiap menyambut Windland Day...",
  ui_story_5009_50091401_75_dialog_content = "Dengan memesan beragam camilan dan minuman melalui Courier Union. Harusnya pesananku tiba besok.",
  ui_story_5009_50091401_76_dialog_content = "PlayerName... Apa terpikir olehmu untuk memeriksa lembar pengeluaran di Colossus sebelum memesan apa pun?!",
  ui_story_5009_50091401_77_dialog_content = "O-omong-omong... Kita harus segera ke Kantor Pos, 'kan? Naroxel masih menunggu kita, lho!",
  ui_story_5009_50091401_78_dialog_content = "Mereka bahkan sudah menyiapkan teh dan camilan untuk kita!",
  ui_story_5009_50091401_79_dialog_content = "Ya! Ayo ke sana!",
  ui_story_5009_50091401_80_dialog_content = "<color=#e8d9bb>Kruuk...</color>",
  ui_story_5009_50091401_81_dialog_content = "Tunggu! Sepertinya barusan aku dengar suara Eclipsite!",
  ui_story_5009_50091401_82_dialog_content = "Kau merasakan sesuatu, PlayerName?",
  ui_story_5009_50091401_83_dialog_content = "Anu... Maaf, tadi itu suara perutku keroncongan...",
  ui_story_5009_50091401_84_dialog_content = "Ternyata salah duga...",
  ui_story_5009_50091401_85_dialog_content = "Karena tak ada yang perlu dikhawatirkan, kita harus bergegas.",
  ui_story_5009_50091401_86_dialog_content = "Kita sudah hampir sampai di Kantor Pos. Jangan buat mereka menunggu lama!",
  ui_story_5009_50091401_87_dialog_content = "Baiklah... Tapi, menurutku, perutku yang keroncongan in bukan hal yang \"tak perlu dikhawatirkan\"...",
  ui_story_5009_50091401_88_dialog_content = "Apa kau masih kuat jalan terus, PlayerName? Apa perlu kuminta Bessie menggendongmu?",
  ui_story_5009_50091401_89_dialog_content = "N-Naroxel?! Ternyata dari tadi kau di sini?",
  ui_story_5009_50091401_90_dialog_content = "Maaf, aku mengagetkanmu, ya?",
  ui_story_5009_50091401_91_dialog_content = "Tweety mulai khawatir karena kalian lama sekali, jadi dia memintaku mencari kalian.",
  ui_story_5009_50091401_92_dialog_content = "Kebetulan saja aku mendengar kata-katamu persis saat aku menemukan kalian...",
  ui_story_5009_50091401_93_dialog_content = "Bu-bukan apa-apa, kok, sungguh...",
  ui_story_5009_50091401_94_dialog_content = "Naroxel, Tweety, kalian perhatian sekali!",
  ui_story_5009_50091401_95_dialog_content = "Tapi... Kok aku tak melihat Tweety di sini?",
  ui_story_5009_50091401_96_dialog_content = "Mungkin dia takut gelap?",
  ui_story_5009_50091401_97_dialog_content = "Tidak, hanya saja... harus ada yang tinggal dan berjaga di Kantor Pos.",
  ui_story_5009_50091401_98_dialog_content = "Menurutku, sepertinya dia sedang sibuk menyiapkan \"kejutan besar\"-nya yang legendaris itu...",
  ui_story_5009_50091401_99_dialog_content = "O-omong-omong... Semuanya, silakan lewat sini!",
  ui_story_5009_50091401_100_dialog_content = "<color=#e8d9bb>Krieeek...</color>",
  ui_story_5009_50091401_101_dialog_content = "Wow...!",
  ui_story_5009_50091401_102_dialog_content = "Rak-raknya, mesin registernya... Semuanya tampak sangat familier.",
  ui_story_5009_50091401_103_dialog_content = "Kalau aku tak salah, Kantor Pos di Lumopolis dirancang mirip seperti ini.",
  ui_story_5009_50091401_104_dialog_content = "Tapi, walau begitu, kotak surat ini sangat berbeda. Ini mengingatkanku akan Soroz...",
  ui_story_5009_50091401_105_dialog_content = "Benar. Ini kotak surat mandiri milik Kantor Pos Eraveil. Para Caelestite sendiri yang merancangnya.",
  ui_story_5009_50091401_106_dialog_content = "Untungnya, kotak surat ini masih berfungsi setelah sekian lama.",
  ui_story_5009_50091401_107_dialog_content = "Hei, lihat apa yang kutemukan di rak ini!",
  ui_story_5009_50091401_108_dialog_content = "Ini kartu pos... Tanggalnya sepuluh tahun lalu! Aku hanya pernah lihat kartu seperti ini di museum!",
  ui_story_5009_50091401_109_dialog_content = "*Terkesiap* Di sini bahkan ada akuarium!",
  ui_story_5009_50091401_110_dialog_content = "Percayalah pada Naroxel. Dia bisa menghadirkan suasana alam ke dalam tempat seperti ini!",
  ui_story_5009_50091401_111_dialog_content = "Soal itu, Dove menghabiskan banyak waktu dan tenaga untuk mencari ikan-ikan yang sekarang ada di dalam akuarium itu.",
  ui_story_5009_50091401_112_dialog_content = "Dove, ya? Aku tak menyangka...",
  ui_story_5009_50091401_113_dialog_content = "Aku sangat iri kepadamu, PlayerName! Tak ada Kantor Pos di Illumina Federation yang terasa senyaman ini!",
  ui_story_5009_50091401_114_dialog_content = "Hmm? Kok kamu diam saja, PlayerName?",
  ui_story_5009_50091401_115_dialog_content = "Aku... aku hanya merasa gembira. Sangat gembira... sampai-sampai aku tak tahu bagaimana harus mengungkapkannya.",
  ui_story_5009_50091401_116_dialog_content = "Lagi pula, ini... Ruang pertama yang diterangi cahaya di Eraveil.",
  ui_story_5009_50091401_117_dialog_content = "Dan ruang ini juga dihias sangat indah... Apa ini sungguh hanya Kantor Pos?",
  ui_story_5009_50091401_118_dialog_content = "Seandainya boleh, aku mau tinggal di sini...",
  ui_story_5009_50091401_119_dialog_content = "Meeoong!",
  ui_story_5009_50091401_120_dialog_content = "Haha! Maaf, sepertinya kau tak akan jadi penghuni pertama di sini!",
  ui_story_5009_50091401_121_dialog_content = "Tahu tidak, PlayerName, kalau kau benar-benar ingin tinggal di sini... tentu saja boleh, sebagai karyawan Courier Union!",
  ui_story_5009_50091401_122_dialog_content = "Tapi, sebelum itu... Apa kau masih ingat surat penerimaan ini?",
  ui_story_5009_50091401_123_dialog_content = "Masih, tapi...",
  ui_story_5009_50091401_124_dialog_content = "Kurasa aku tak akan bisa memahaminya, sekarang aku sudah terlalu lelah untuk membaca.",
  ui_story_5009_50091401_125_dialog_content = "Naroxel, mungkin bisa kaujelaskan saja poin-poin utamanya kepada PlayerName? Begitu juga tak apa, 'kan?",
  ui_story_5009_50091401_126_dialog_content = "Tak apa. Kalau rekonstruksi yang dilakukan Courier Union atas Kantor Pos ini sudah sesuai dengan harapanmu...",
  ui_story_5009_50091401_127_dialog_content = "Sebenarnya, hasilnya malah lebih baik dari harapanku... Beratus-ratus kali lipat lebih baik!",
  ui_story_5009_50091401_128_dialog_content = "Terima kasih atas masukanmu. Kalau begitu, tolong bubuhkan tanda tangan dan namamu di bawah ini, dan ingat...",
  ui_story_5009_50091401_129_dialog_content = "Setelah kau menandatanganinya, berarti kontrakmu dengan Kantor Pos kami secara resmi mulai berlaku.",
  ui_story_5009_50091401_130_dialog_content = "Apa maksudmu \"secara resmi mulai berlaku\"?",
  ui_story_5009_50091401_131_dialog_content = "Dalam jaringan transportasi Courier Union, tengara Kantor Pos Eraveil akan kembali diaktifkan.",
  ui_story_5009_50091401_132_dialog_content = "Dengan kata lain, Eraveil akan bisa menerima surat dari seluruh penjuru dunia.",
  ui_story_5009_50091401_133_dialog_content = "(Dulu, sebelum musibah itu... Apakah masyarakat Eraveil kemari untuk mengambil surat dari Illumina dan Lumopolis...)",
  ui_story_5009_50091401_134_dialog_content = "(Dan bahkan dari Northland?)",
  ui_story_5009_50091401_135_dialog_content = "(Apa itu berarti... para Caelestite juga menggunakan tempat ini...)",
  ui_story_5009_50091401_136_dialog_content = "(Untuk mengirimkan pesan ke seluruh dunia? Surat yang berisi kegembiraan dan kesedihan?)",
  ui_story_5009_50091401_137_dialog_content = "(Kalau kutandatangani surat kontraknya, Kantor Pos ini akan kembali berfungsi.. Seperti tujuh belas tahun lalu.)",
  ui_story_5009_50091401_138_dialog_content = "(Kalau kutandatangani surat kontraknya, Eraveil akan kembali muncul di setiap peta di dunia...)",
  ui_story_5009_50091401_139_dialog_content = "Apa kau masih punya pertanyaan atau kekhawatiran, PlayerName?",
  ui_story_5009_50091401_140_dialog_content = "Tidak, aku hanya perlu tahu di mana aku harus membubuhkan tanda tangan. Aku akan...",
  ui_story_5009_50091401_141_dialog_content = "Membuat Eraveil hidup kembali!",
  ui_story_5009_50091401_142_dialog_content = "Silakan, di sini. Aku tak percaya, baru kali ini kulihat ada orang yang begitu bersemangat menandatangani surat kontrak kerja!",
  ui_story_5009_50091401_143_dialog_content = "Tertanda:",
  ui_story_5009_50091401_A1_dialog_content = "...",
  ui_story_5009_50091401_144_option_content = "PlayerName",
  ui_story_5009_50091401_145_dialog_content = "<color=#e8d9bb>Gong... Gong... Gong...</color>",
  ui_story_5009_50091401_146_dialog_content = "Apa ini sudah tengah malam?",
  ui_story_5009_50091401_147_dialog_content = "Aku tak sadar, rupanya sudah selarut ini...",
  ui_story_5009_50091401_148_dialog_content = "Hari sudah berganti... Artinya, sekarang saatnya...",
  ui_story_5009_50091401_149_dialog_content = "Grrr...",
  ui_story_5009_50091401_150_dialog_content = "Hah? Carleen, awas!",
  ui_story_5009_50091401_151_dialog_content = "Ice Blossom! Menyebar!",
  ui_story_5009_50091401_152_dialog_content = "Apa ini... Soroz?",
  ui_story_5009_50091401_153_dialog_content = "Tapi, materialnya... Ini boneka Soroz!",
  ui_story_5009_50091401_154_dialog_content = "Ini... Imut... Sekali! Dari mana asalnya, ya?",
  ui_story_5009_50091401_155_dialog_content = "Pasti ini kejutan yang dimaksud Tweety. Ternyata memang kejutan yang membuat terkesima...",
  ui_story_5009_50091401_156_dialog_content = "Akhiwnya kalian ingat kepadaku!",
  ui_story_5009_50091401_157_dialog_content = "Eh? Apa barusan itu Tweety? Aku dengar suaranya, tapi kok dia sama sekali tak kelihatan...",
  ui_story_5009_50091401_158_dialog_content = "Aku di bawah sini... Aku tewpewangkap es Nona Carween!",
  ui_story_5009_50091401_159_dialog_content = "Aku tak punya pilihan, tadi aku khawatir Tweety juga akan jatuh... Biar kucairkan esnya.",
  ui_story_5009_50091401_160_dialog_content = "Tewima kasih, Nona Carween! Tapi... Apa kau lupa bahwa aku punya sayap?",
  ui_story_5009_50091401_161_dialog_content = "Tapi, dibekukan sepewti tadi itu... Wasanya lumayan sewu!",
  ui_story_5009_50091401_162_dialog_content = "Kalau begitu, apa kamu ingin kubekukan lagi?",
  ui_story_5009_50091401_163_dialog_content = "T-tidak, terima kasih! Sekali saja sudah cukup...",
  ui_story_5009_50091401_164_dialog_content = "Apa dari tadi kau menunggu di kayu palang atap itu, Tweety?",
  ui_story_5009_50091401_165_dialog_content = "Yap! Dawi tadi aku menunggu kawian semua!",
  ui_story_5009_50091401_166_dialog_content = "Dengan begitu, aku bisa tiba-tiba masuk dengan wejutan besawku!",
  ui_story_5009_50091401_167_dialog_content = "Tapi... aku malah ketiduwan... dan aku tewbangun gawa-gawa suwawa lonceng itu...",
  ui_story_5009_50091401_168_dialog_content = "Maaf, PlayerName... Wejutan besawku tewnyata mengecewakan...",
  ui_story_5009_50091401_169_dialog_content = "Kau tak perlu minta maaf, Tweety! Lagi pula, kau sudah membuat tempat ini tampak begitu indah... Aku bahkan belum sempat berterima kasih dengan layak kepadamu.",
  ui_story_5009_50091401_170_dialog_content = "Oh, iya, lonceng penanda tengah malamnya baru saja berdentang, dan itu berarti hari ini Windland Festival berlangsung.",
  ui_story_5009_50091401_171_dialog_content = "Dari yang tertulis di buku, pada hari besar ini, kaum Caelestite juga biasa menggantung boneka seperti ini.",
  ui_story_5009_50091401_172_dialog_content = "Kejutan darimu ini sangat sempurna untuk perayaan ini!",
  ui_story_5009_50091401_173_dialog_content = "Wu-wungguh? Aku sangat senang mendengawnya!",
  ui_story_5009_50091401_174_dialog_content = "Jadi, kau benaw-benaw suka dengan wejutanku, PlayerName?",
  ui_story_5009_50091401_175_dialog_content = "Tentu saja! Tapi, dari mana kaudapat benda seperti ini?",
  ui_story_5009_50091401_176_dialog_content = "Ini adalah, anu... kami berusaha sebaik mungkin untuk membuat Soroz berukuran mini.",
  ui_story_5009_50091401_177_dialog_content = "Memang sama sekali tidak sempurna... Tapi, kami BENAR-BENAR mengisinya dengan camilan sungguhan!",
  ui_story_5009_50091401_178_dialog_content = "Ini juga cara kami untuk mendoakan yang terbaik untukmu, PlayerName!",
  ui_story_5009_50091401_179_dialog_content = "Boneka ini kelihatan persis seperti Soroz! Lagi pula, ini lebih baik dari semua hasil karyaku...",
  ui_story_5009_50091401_180_dialog_content = "Oh? Apa maksudmu boneka laba-laba di Colossus itu? Yang matanya seperti kodok dan punya sayap seperti kelelawar...",
  ui_story_5009_50091401_181_dialog_content = "Itu hasil buatanmu, PlayerName?",
  ui_story_5009_50091401_182_dialog_content = "He-hentikan, Vice! Jangan sampai mereka semua tahu...",
  ui_story_5009_50091401_183_dialog_content = "Bagaimana menuwutmu, PlayerName? Mau mewobeknya dan mengambiw camiwan di dawamnya?",
  ui_story_5009_50091401_184_dialog_content = "Aku sendiwi yang memilihnya, khusus untukmu!",
  ui_story_5009_50091401_185_dialog_content = "Tapi kau dan Naroxel sudah berusaha keras untuk membuatnya, Tweety. Lagi pula, bentuknya sangat mirip dengan Soroz...",
  ui_story_5009_50091401_186_dialog_content = "Sepertinya aku tak akan tega merobeknya.",
  ui_story_5009_50091401_187_dialog_content = "Ta-tapi, kalau kau tak mewobeknya, jadinya bukan pewayaan sungguhan, dong, PlayerName...",
  ui_story_5009_50091401_188_dialog_content = "Apa kau sudah lupa, Tweety?",
  ui_story_5009_50091401_189_dialog_content = "Ah! Benaw! Nona Dove juga membuat lampu-lampu tewbang yang indah itu!",
  ui_story_5009_50091401_190_dialog_content = "Lampu... terbang?",
  ui_story_5009_50091401_191_dialog_content = "Apa maksudnya Lentera Dandelion yang biasanya dipasang para Caelestite saat hari besar?",
  ui_story_5009_50091401_192_dialog_content = "Tunggu... Dove bisa membuat Lentera Dandelion?!",
  ui_story_5009_50091401_193_dialog_content = "Tadi aku memang sudah tanya, tapi apa yang kita bicarakan ini memang Dove yang sama?!",
  ui_story_5009_50091401_194_dialog_content = "Dove memang bilang dia belajar banyak di Illumina...",
  ui_story_5009_50091401_195_dialog_content = "Dan dia kebetulan menemukan panduan petunjuk cara membuat Lentera Dandelion. Jadi, dia mengambilnya tanpa pikir panjang.",
  ui_story_5009_50091401_196_dialog_content = "Aku tak sabaw ingin bewmain-main dengan lampu-lampu cantik itu!",
  ui_story_5009_50091401_197_dialog_content = "Ayo kita ke jembatan!",
  ui_story_5009_50091401_198_dialog_content = "Ha-hati-hati, Tweety! Jangan lari cepat-cepat!",
  ui_story_5009_50091401_199_dialog_content = "Tak apa! Ingat, aku punya sayap, lho!",
  ui_story_5009_50091401_200_dialog_content = "<color=#e8d9bb>Brak...!</color>",
  ui_story_5009_50091401_201_dialog_content = "Aduh...",
  ui_story_5009_50091401_202_dialog_content = "Kau baik-baik saja, Tweety? Barusan kau jatuh berdebam! Sakitkah?",
  ui_story_5009_50091401_203_dialog_content = "Tewima kasih, Nona Vice... Aku sudah tak apa-apa.",
  ui_story_5009_50091401_204_dialog_content = "Tadi aku hanya menabwak sebuah lentewa yang menyala... Tadi aku tewbakaw sedikit, tapi sekawang sudah tak apa-apa, kok!",
  ui_story_5009_50091401_205_dialog_content = "Kalau sudah dinyalakan, lentera itu memang tampak seperti dandelion...",
  ui_story_5009_50091401_206_dialog_content = "Hei, PlayerName! Hitung sampai tiga! Nanti kami akan menerbangkan Lentera Dandelion kami bersamaan. Oke?",
  ui_story_5009_50091401_207_dialog_content = "Tentu saja! Satu... Dua... Tiga! Nyalakan!",
  ui_story_5009_50091401_208_dialog_content = "Terbang, terbang, terbang!",
  ui_story_5009_50091401_209_dialog_content = "Lentera yang berpijar di tengah jutaan bintang dan aurora yang gemilang... Sungguh suatu pemandangan langka yang membuat mata dan hati terkesima.",
  ui_story_5009_50091401_210_dialog_content = "Sudah lama sekali aku tak mendengarmu mengucapkan kalimat sepuitis itu, Carleen!",
  ui_story_5009_50091401_211_dialog_content = "Hari besar seperti ini tak akan lengkap tanpa sedikit sentuhan puisi.",
  ui_story_5009_50091401_212_dialog_content = "Seharusnya dulu kau mengikuti lebih banyak mata pelajaran sastra saat bersekolah di Lumopolis, Vice.",
  ui_story_5009_50091401_213_dialog_content = "Kalau begitu, kita bertanding membuat puisi saja.",
  ui_story_5009_50091401_214_dialog_content = "Aku tak pernah bisa memahami sastra atau puisi, tapi kini...",
  ui_story_5009_50091401_215_dialog_content = "Sekilas, aku merasa seakan-akan orang-orang yang sudah lama tiada kini kembali berada di sisiku.",
  ui_story_5009_50091401_216_dialog_content = "Lalu, mereka tertawa sambil berbalik, pergi sambil membawa serta pikiran dan harapanku...",
  ui_story_5009_50091401_217_dialog_content = "Kurasa sebaiknya kita cepat-cepat mengucapkan harapan kita!",
  ui_story_5009_50091401_218_dialog_content = "Tapi, seingatku tak ada tradisi seperti itu dalam Windland Festival, 'kan? Bagaimana menurutmu, PlayerName?",
  ui_story_5009_50091401_219_dialog_content = "Semuanya, lihat di sana! Apa aku berkhayal, atau memang ada sesuatu yang terbang ke arah kita?",
  ui_story_5009_50091401_220_dialog_content = "Sesuai dugaan, sepertinya Kantor Pos ini sudah akan langsung sibuk sejak hari pertama beroperasi.",
  ui_story_5009_50091401_221_dialog_content = "Kalau begitu, benda-benda di langit itu...",
  ui_story_5009_50091401_222_dialog_content = "Aku yakin itu adalah para kurir yang mengantarkan surat dari seluruh penjuru dunia, PlayerName.",
  ui_story_5009_50091401_223_dialog_content = "Aku tak tahu ternyata Courier Union bekerja secepat itu...",
  ui_story_5009_50091401_224_dialog_content = "PlayerName baru saja menandatangani kontraknya beberapa menit lalu, dan sekarang mereka sudah berdatangan!",
  ui_story_5009_50091401_225_dialog_content = "Kalau begitu, surat yang mereka bawa itu...",
  ui_story_5009_50091401_226_dialog_content = "Benar sekali. Mereka membawa surat yang dialamatkan ke penduduk Eraveil dalam tujuh belas tahun terakhir ini.",
  ui_story_5009_50091401_227_dialog_content = "Dan hari ini, pada hari Windland Festival...",
  ui_story_5009_50091401_228_dialog_content = "Harapan, kekhawatiran, suara mereka... akhirnya tiba juga di tujuan.",
  ui_story_5009_50091401_229_dialog_content = "Walau begitu, aku sama sekali tak pernah menyangka...",
  ui_story_5009_50091401_230_dialog_content = "Bahwa akan ada begitu banyak kurir yang akan mengantarkan surat-surat yang sudah tertunda selama tujuh belas tahun itu sekaligus. Ini sungguh pemandangan langka.",
  ui_story_5009_50091401_231_dialog_content = "Dalam beberapa hari ke depan, kau akan sangat sibuk, Tweety.",
  ui_story_5009_50091401_232_dialog_content = "Yap! Untungnya, aku suka pekewjaanku!",
  ui_story_5009_50091401_233_dialog_content = "Seandainya saja Tweety bisa bekerja di Illumina...",
  ui_story_5009_50091401_234_dialog_content = "Pasti menyenangkan sekali! Jadi, aku bisa bewtemu dengan Nona Dove setiap hawi!",
  ui_story_5009_50091401_235_dialog_content = "Tapi, aku tak tahu apa kami bisa menangani teman-teman kami dawi Northland...",
  ui_story_5009_50091401_236_dialog_content = "Aku bawu saja mewihat sawah satu teman baikku! Dia kemawi untuk mengantawkan suwat!",
  ui_story_5009_50091401_237_dialog_content = "Jangan tergesa-gesa, Tweety...!",
  ui_story_5009_50091401_238_dialog_content = "<color=#e8d9bb>Brak...!</color>",
  ui_story_5009_50091401_239_dialog_content = "Aduh... Apa nih yang di mukaku? Gataw...",
  ui_story_5009_50091401_240_dialog_content = "Kau baru saja menabrak salah satu Lentera Dandelion, Tweety... Wajahmu penuh bulu putih!",
  ui_story_5009_50091401_241_dialog_content = "Hahaha! Menggemaskan sekali! Bulu-bulu itu cocok dengannya!",
  ui_story_5009_50091401_242_dialog_content = "Heh...",
  ui_story_5009_50091401_243_dialog_content = "*Terkesiap* Aku bewhasil! Akhiwnya aku bewhasil membuat Nona Carween tewsenyum! Hahaha!",
  ui_story_5009_50091401_244_dialog_content = "Hahahahaha!",
  ui_story_5009_50091401_245_dialog_content = "Begitulah kami merayakan Windland Festival pertamaku.",
  ui_story_5009_50091401_246_dialog_content = "Sebelum festival itu...",
  ui_story_5009_50091401_247_dialog_content = "Yang ada hanyalah rasa sakit...",
  ui_story_5009_50091401_248_dialog_content = "Yang ada hanyalah amarah...",
  ui_story_5009_50091401_249_dialog_content = "Lalu, ada perubahan...",
  ui_story_5009_50091401_250_dialog_content = "Dan ada salam perpisahan...",
  ui_story_5009_50091401_251_dialog_content = "Ternyata, di dunia ini ada banyak orang sepertiku.",
  ui_story_5009_50091401_252_dialog_content = "Tapi, karena pilihan kami sendiri, kami menempuh jalan hidup yang berbeda-beda.",
  ui_story_5009_50091401_253_dialog_content = "Saat garis takdir kami tak lagi sejalan, yang bisa kami lakukan hanyalah mengucapkan salam perpisahan...",
  ui_story_5009_50091401_254_dialog_content = "Tapi, kurasa, asalkan kita mengambil pilihan dengan penuh kesadaran, mungkin suatu hari nanti kami akan bisa berteman.",
  ui_story_5009_50091401_255_dialog_content = "Dan, suatu hari nanti, para pengkhianat kejam dan egois itu juga akan mendapatkan ganjaran yang setimpal.",
  ui_story_5009_50091401_256_dialog_content = "Setelah segala yang sudah kulalui, mau tak mau aku merasa makin bersyukur karena aku mendapatkan banyak teman dalam perjalananku.",
  ui_story_5009_50091401_257_dialog_content = "Terutama... pada hari besar seperti ini.",
  ui_story_5009_50091401_258_dialog_content = "Dulu, aku menganggap hari besar sama saja dengan hari-hari biasa lainnya. Aku tak paham apa maknanya merayakan sesuatu.",
  ui_story_5009_50091401_259_dialog_content = "Tapi, kini, akhirnya aku paham.",
  ui_story_5009_50091401_260_dialog_content = "Pada hari istimewa, bisa merayakan kenangan bersama teman-teman, dan berbagi harapan untuk masa depan...",
  ui_story_5009_50091401_261_dialog_content = "Ini sungguh pengalaman yang hangat dan membahagiakan.",
  ui_story_5009_50091401_262_dialog_content = "Beberapa hari belakangan ini, sepanjang hari, Kantor Pos menerima banyak surat dari seluruh penjuru dunia.",
  ui_story_5009_50091401_263_dialog_content = "Walaupun sebagian besar surat itu tidak ditujukan untukku...",
  ui_story_5009_50091401_264_dialog_content = "Naroxel bilang, sebagai orang terakhir dari kaum Caelestite, aku bisa bertindak sebagai satu-satunya wakil mereka dan membuka surat-surat itu kalau aku mau.",
  ui_story_5009_50091401_265_dialog_content = "\"Membalas doa-doa penuh harapan dari semua orang ternyata adalah hal yang sangat romantis.\"",
  ui_story_5009_50091401_266_dialog_content = "Apakah kaumku yang telah tiada ingin aku terus membawa pikiran dan perasaan mereka?",
  ui_story_5009_50091401_267_dialog_content = "Semua orang bilang, tentu saja itulah yang mereka inginkan...",
  ui_story_5009_50091401_268_dialog_content = "Tapi, sebelum itu, aku sudah memutuskan... bahwa aku harus mengirimkan surat pertamaku dari Eraveil.",
  ui_story_5009_50091401_269_dialog_content = "Selama ini aku sudah terbiasa menulis buku harian. Tapi, menulis surat ternyata terasa berbeda.",
  ui_story_5009_50091401_270_dialog_content = "Aku terus-menerus khawatir kalau bahasaku tak pantas. Berulang kali kuhapus dan kutulis ulang suratku itu...",
  ui_story_5009_50091401_271_dialog_content = "Lagi pula, aku mewakili semua kaum Caelestite untuk menyampaikan terima kasih atas segala yang sudah mereka lakukan bagi kami.",
  ui_story_5009_50091401_272_dialog_content = "Hmm... Aku ingin tahu apakah mereka sudah menerima suratku...",
  ui_story_5009_50091401_273_dialog_content = "Keluarga Lin di Umbraton..."
}
return config
